-- The schema of every module as a fresh install makes it. Generated by `make schema` from the migrations: do
-- not edit (a test fails when it is stale). Seed rows are in the migrations, not here.
-- Schema epoch 2.

-- ======== vedette.db ========

-- schema epoch (core/store)

CREATE TABLE core_schema_epoch (
    id    INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    epoch INTEGER NOT NULL CHECK (epoch >= 1),
    rev   TEXT    NOT NULL CHECK (length(rev) = 64)
);

-- module core

CREATE TABLE core_secret (
    id          TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    purpose     TEXT    NOT NULL CHECK (length(purpose) BETWEEN 1 AND 64),
    nonce       BLOB    NOT NULL CHECK (typeof(nonce) = 'blob' AND length(nonce) = 12),
    ciphertext  BLOB    NOT NULL CHECK (typeof(ciphertext) = 'blob' AND length(ciphertext) >= 16), -- includes the 16-byte GCM tag
    key_version INTEGER NOT NULL CHECK (key_version >= 1),
    last4       TEXT    CHECK (last4 IS NULL OR length(last4) = 4),
    created_at  TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    rotated_at  TEXT    CHECK (rotated_at IS NULL OR rotated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE core_audit (
    seq       INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    id        TEXT    NOT NULL UNIQUE CHECK (length(id) BETWEEN 1 AND 96),
    prev_hash TEXT    NOT NULL CHECK (length(prev_hash) = 64),
    hash      TEXT    NOT NULL UNIQUE CHECK (length(hash) = 64),
    ts        TEXT    NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    user      TEXT    NOT NULL CHECK (length(user) > 0),
    action    TEXT    NOT NULL CHECK (length(action) > 0),
    target    TEXT    NOT NULL CHECK (length(target) > 0),
    detail    TEXT
);

CREATE TABLE core_chain_anchor (
    chain            TEXT NOT NULL PRIMARY KEY CHECK (chain IN ('core_audit', 'ai_activity', 'resp_log')),
    last_pruned_id   TEXT NOT NULL,
    last_pruned_hash TEXT NOT NULL CHECK (length(last_pruned_hash) = 64),
    pruned_at        TEXT NOT NULL CHECK (pruned_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE core_module (
    id          TEXT    NOT NULL PRIMARY KEY CHECK (id GLOB '[a-z]*' AND length(id) BETWEEN 1 AND 32),
    enabled     BOOLEAN NOT NULL CHECK (enabled IN (0, 1)),
    enabled_at  TEXT    CHECK (enabled_at IS NULL OR enabled_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    disabled_at TEXT    CHECK (disabled_at IS NULL OR disabled_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    version     TEXT    NOT NULL CHECK (length(version) BETWEEN 1 AND 64)
);

CREATE TABLE core_job_run (
    id          TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    module      TEXT NOT NULL CHECK (length(module) BETWEEN 1 AND 32),
    job         TEXT NOT NULL CHECK (length(job) BETWEEN 1 AND 64),
    started_at  TEXT NOT NULL CHECK (started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    finished_at TEXT NOT NULL CHECK (finished_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    status      TEXT NOT NULL CHECK (status IN ('ok', 'error', 'cancelled')),
    error       TEXT CHECK (error IS NULL OR length(error) <= 1000)
);

CREATE TABLE core_user (
    id            TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name          TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    email         TEXT    NOT NULL UNIQUE CHECK (email = lower(email) AND length(email) BETWEEN 3 AND 320),
    role          TEXT    NOT NULL CHECK (role IN ('viewer', 'operator', 'admin')),
    password_hash TEXT    NOT NULL CHECK (length(password_hash) BETWEEN 1 AND 512), -- argon2id PHC string
    cred_version  INTEGER NOT NULL DEFAULT 0 CHECK (cred_version >= 0), -- +1 on every real password change or reset (not on a rehash with new argon2 parameters)
    twofa_method  TEXT    CHECK (twofa_method IS NULL OR twofa_method IN ('app', 'email')),
    disabled      INTEGER NOT NULL DEFAULT 0 CHECK (disabled IN (0, 1)),
    created_at    TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_login    TEXT    CHECK (last_login IS NULL OR last_login GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, temp_password_expires_at TEXT CHECK (temp_password_expires_at IS NULL OR temp_password_expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), sso_issuer TEXT CHECK (sso_issuer IS NULL OR (sso_issuer GLOB 'https://*' AND length(sso_issuer) <= 2048)), sso_subject TEXT CHECK (sso_subject IS NULL OR length(sso_subject) BETWEEN 1 AND 255));

CREATE TABLE core_user_totp (
    user_id   TEXT    NOT NULL PRIMARY KEY REFERENCES core_user (id) ON DELETE CASCADE,
    secret_id TEXT    NOT NULL REFERENCES core_secret (id),
    confirmed INTEGER NOT NULL DEFAULT 0 CHECK (confirmed IN (0, 1)),
    last_step INTEGER CHECK (last_step IS NULL OR last_step >= 0),
    created_at TEXT   NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE core_email_code (
    user_id    TEXT    NOT NULL PRIMARY KEY REFERENCES core_user (id) ON DELETE CASCADE,
    code_hash  TEXT    NOT NULL CHECK (length(code_hash) = 64), -- hex HMAC-SHA-256 of user id and the 6 digits
    expires_at TEXT    NOT NULL CHECK (expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    tries      INTEGER NOT NULL DEFAULT 0 CHECK (tries BETWEEN 0 AND 5),
    sent_at    TEXT    NOT NULL CHECK (sent_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE core_email_code_send (
    user_id TEXT NOT NULL REFERENCES core_user (id) ON DELETE CASCADE,
    sent_at TEXT NOT NULL CHECK (sent_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, kind TEXT NOT NULL DEFAULT 'signin' CHECK (kind IN ('signin', 'stepup')));

CREATE TABLE core_session (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    user_id    TEXT NOT NULL REFERENCES core_user (id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64), -- SHA-256 of the __Host-vedette_session cookie
    csrf_hash  TEXT NOT NULL CHECK (length(csrf_hash) = 64),         -- SHA-256 of the __Host-vedette_csrf cookie
    device     TEXT NOT NULL CHECK (length(device) <= 200),
    ip         TEXT NOT NULL CHECK (length(ip) BETWEEN 1 AND 64),
    started_at TEXT NOT NULL CHECK (started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    expires_at TEXT NOT NULL CHECK (expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    revoked_at TEXT CHECK (revoked_at IS NULL OR revoked_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE core_org (
    id             INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    name           TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    timezone       TEXT    NOT NULL DEFAULT 'Asia/Ho_Chi_Minh' CHECK (length(timezone) BETWEEN 1 AND 64),
    setup_complete INTEGER NOT NULL DEFAULT 0 CHECK (setup_complete IN (0, 1)),
    data_mode      TEXT    NOT NULL DEFAULT 'clean' CHECK (data_mode IN ('sample', 'clean')),
    install_id     TEXT    NOT NULL CHECK (length(install_id) BETWEEN 1 AND 96)
);

CREATE TABLE core_setting (
    key        TEXT NOT NULL PRIMARY KEY CHECK (length(key) BETWEEN 1 AND 96),
    value      TEXT NOT NULL CHECK (json_valid(value)),
    updated_at TEXT NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by TEXT NOT NULL CHECK (length(updated_by) BETWEEN 1 AND 320)
);

CREATE TABLE core_chain_head (
    chain      TEXT    NOT NULL PRIMARY KEY CHECK (chain IN ('core_audit', 'ai_activity', 'resp_log')),
    last_hash  TEXT    NOT NULL CHECK (length(last_hash) = 64),
    count      INTEGER NOT NULL CHECK (count >= 0),
    updated_at TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE core_connection (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name       TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 40),
    name_key   TEXT    NOT NULL UNIQUE CHECK (length(name_key) BETWEEN 1 AND 160), -- the name in lower case for every script: names are unique in any letter case
    kind       TEXT    NOT NULL CHECK (kind IN ('http', 'ssh', 'netconf-restconf', 'automation', 'mcp-http')),
    target     TEXT    NOT NULL CHECK (length(target) BETWEEN 1 AND 2048),
    asset_id   TEXT    CHECK (asset_id IS NULL OR length(asset_id) BETWEEN 1 AND 96),
    auth_type  TEXT    NOT NULL CHECK (auth_type IN ('none', 'token', 'basic', 'ssh-key')),
    username   TEXT    CHECK (username IS NULL OR length(username) BETWEEN 1 AND 64),
    secret_id  TEXT    REFERENCES core_secret (id),
    key_fp     TEXT    CHECK (key_fp IS NULL OR length(key_fp) BETWEEN 8 AND 100),
    pin        TEXT    CHECK (pin IS NULL OR length(pin) BETWEEN 1 AND 300),
    pin_seen   TEXT    CHECK (pin_seen IS NULL OR pin_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    allow      TEXT    NOT NULL CHECK (json_valid(allow) AND json_type(allow) = 'array'),
    enabled    BOOLEAN NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    status     TEXT    NOT NULL DEFAULT 'untested' CHECK (status IN ('ok', 'error', 'untested')),
    last_test  TEXT    CHECK (last_test IS NULL OR last_test GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((auth_type = 'none') = (secret_id IS NULL))
);

CREATE TABLE core_connection_tool (
    connection_id TEXT    NOT NULL REFERENCES core_connection (id) ON DELETE CASCADE,
    name          TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 64),
    pos           INTEGER NOT NULL CHECK (pos >= 0),
    access        TEXT    NOT NULL CHECK (access IN ('read', 'write')),
    description   TEXT    NOT NULL CHECK (length(description) <= 200),
    enabled       BOOLEAN NOT NULL CHECK (enabled IN (0, 1)), ident TEXT NOT NULL DEFAULT '' CHECK (length(ident) <= 64),
    PRIMARY KEY (connection_id, name)
) WITHOUT ROWID;

CREATE TABLE core_sensor_cert (
    serial     TEXT NOT NULL PRIMARY KEY CHECK (length(serial) BETWEEN 1 AND 64 AND serial NOT GLOB '*[^0-9a-f]*'), -- hex of the x509 serial
    role       TEXT NOT NULL CHECK (role IN ('passive', 'active')),
    not_after  TEXT NOT NULL CHECK (not_after GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    retired_at TEXT CHECK (retired_at IS NULL OR retired_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE INDEX core_audit_ts_idx ON core_audit (ts);

CREATE INDEX core_job_run_job_idx ON core_job_run (module, job, started_at);

CREATE INDEX core_user_role_idx ON core_user (role);

CREATE INDEX core_email_code_send_user_idx ON core_email_code_send (user_id, sent_at);

CREATE INDEX core_session_user_idx ON core_session (user_id);

CREATE INDEX core_sensor_cert_live ON core_sensor_cert (role) WHERE retired_at IS NULL;

CREATE UNIQUE INDEX core_user_sso_idx ON core_user (sso_issuer, sso_subject) WHERE sso_issuer IS NOT NULL;

CREATE TRIGGER core_audit_no_update BEFORE UPDATE ON core_audit
BEGIN
    SELECT RAISE(ABORT, 'core_audit is append-only');
END;

CREATE TRIGGER core_audit_no_replace BEFORE INSERT ON core_audit
WHEN EXISTS (SELECT 1 FROM core_audit WHERE id = NEW.id OR hash = NEW.hash OR seq = NEW.seq)
BEGIN
    SELECT RAISE(ABORT, 'core_audit is append-only');
END;

CREATE TRIGGER core_audit_no_delete BEFORE DELETE ON core_audit
WHEN OLD.seq > COALESCE((SELECT a.seq FROM core_audit a JOIN core_chain_anchor c ON c.last_pruned_id = a.id WHERE c.chain = 'core_audit'), 0)
BEGIN
    SELECT RAISE(ABORT, 'core_audit is append-only');
END;

CREATE TABLE core_run (
    id            TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    module        TEXT    NOT NULL CHECK (length(module) BETWEEN 1 AND 32),
    kind          TEXT    NOT NULL CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    lane          TEXT    NOT NULL CHECK (length(lane) BETWEEN 1 AND 40 AND lane NOT GLOB '*[^a-z0-9_]*'),
    title         TEXT    NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
    trigger       TEXT    NOT NULL CHECK (trigger IN ('manual', 'schedule', 'event')),
    trigger_note  TEXT    CHECK (trigger_note IS NULL OR length(trigger_note) BETWEEN 1 AND 200),
    requested_by  TEXT    NOT NULL CHECK (length(requested_by) BETWEEN 1 AND 320), -- an email, or system
    schedule_id   TEXT    REFERENCES core_schedule (id) ON DELETE SET NULL,
    subject_kind  TEXT    CHECK (subject_kind IS NULL OR (length(subject_kind) BETWEEN 1 AND 40 AND subject_kind NOT GLOB '*[^a-z0-9_]*')),
    subject_id    TEXT    CHECK (subject_id IS NULL OR length(subject_id) BETWEEN 1 AND 96),
    subject_label TEXT    CHECK (subject_label IS NULL OR length(subject_label) BETWEEN 1 AND 200), -- a snapshot: it outlives its subject
    parent_id     TEXT    REFERENCES core_run (id) ON DELETE CASCADE,
    status        TEXT    NOT NULL CHECK (length(status) BETWEEN 1 AND 40 AND status NOT GLOB '*[^a-z0-9_]*'),
    waiting_for   TEXT    CHECK (waiting_for IS NULL OR length(waiting_for) BETWEEN 1 AND 200),
    stop_reason   TEXT    CHECK (stop_reason IS NULL OR length(stop_reason) BETWEEN 1 AND 500),
    error         TEXT    CHECK (error IS NULL OR length(error) BETWEEN 1 AND 1000),
    total         INTEGER NOT NULL DEFAULT 0 CHECK (total >= 0),
    done          INTEGER NOT NULL DEFAULT 0 CHECK (done >= 0),
    queued_at     TEXT    NOT NULL CHECK (queued_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    started_at    TEXT    CHECK (started_at IS NULL OR started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    ended_at      TEXT    CHECK (ended_at IS NULL OR ended_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at    TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((subject_kind IS NULL) = (subject_id IS NULL))
);

CREATE TABLE core_run_step (
    run_id     TEXT    NOT NULL REFERENCES core_run (id) ON DELETE CASCADE,
    seq        INTEGER NOT NULL CHECK (seq >= 1),
    name       TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 200),
    status     TEXT    NOT NULL CHECK (length(status) BETWEEN 1 AND 40 AND status NOT GLOB '*[^a-z0-9_]*'),
    total      INTEGER NOT NULL DEFAULT 0 CHECK (total >= 0),
    done       INTEGER NOT NULL DEFAULT 0 CHECK (done >= 0),
    note       TEXT    CHECK (note IS NULL OR length(note) BETWEEN 1 AND 500),
    started_at TEXT    CHECK (started_at IS NULL OR started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    ended_at   TEXT    CHECK (ended_at IS NULL OR ended_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    PRIMARY KEY (run_id, seq)
) WITHOUT ROWID;

CREATE TABLE core_run_item (
    run_id       TEXT    NOT NULL REFERENCES core_run (id) ON DELETE CASCADE,
    seq          INTEGER NOT NULL CHECK (seq >= 1),
    subject_kind TEXT    NOT NULL CHECK (length(subject_kind) BETWEEN 1 AND 40 AND subject_kind NOT GLOB '*[^a-z0-9_]*'),
    subject_id   TEXT    CHECK (subject_id IS NULL OR length(subject_id) BETWEEN 1 AND 96), -- NULL: an address no device has yet
    label        TEXT    NOT NULL CHECK (length(label) BETWEEN 1 AND 200),
    outcome      TEXT    NOT NULL CHECK (length(outcome) BETWEEN 1 AND 40 AND outcome NOT GLOB '*[^a-z0-9_]*'),
    note         TEXT    CHECK (note IS NULL OR length(note) BETWEEN 1 AND 500),
    PRIMARY KEY (run_id, seq)
) WITHOUT ROWID;

CREATE TABLE core_run_log (
    id     INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    run_id TEXT    NOT NULL REFERENCES core_run (id) ON DELETE CASCADE,
    ts     TEXT    NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    level  TEXT    NOT NULL CHECK (level IN ('info', 'warn', 'error')),
    text   TEXT    NOT NULL CHECK (length(text) BETWEEN 1 AND 1000)
);

CREATE UNIQUE INDEX core_run_live ON core_run (lane) WHERE status IN ('running', 'stopping');

CREATE INDEX core_run_queued_idx ON core_run (queued_at);

CREATE INDEX core_run_status_idx ON core_run (status, queued_at);

CREATE INDEX core_run_subject_idx ON core_run (subject_kind, subject_id, queued_at);

CREATE INDEX core_run_kind_idx ON core_run (module, kind, queued_at);

CREATE INDEX core_run_parent_idx ON core_run (parent_id);

CREATE INDEX core_run_log_run_idx ON core_run_log (run_id, id);

CREATE INDEX core_run_log_ts_idx ON core_run_log (ts);

CREATE INDEX core_run_schedule_idx ON core_run (schedule_id);

CREATE TABLE core_schedule (
    id               TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    owner_module     TEXT    NOT NULL CHECK (length(owner_module) BETWEEN 1 AND 32),
    owner_key        TEXT    NOT NULL UNIQUE CHECK (length(owner_key) BETWEEN 1 AND 160),
    enabled          INTEGER NOT NULL CHECK (enabled IN (0, 1)),
    paused_until     TEXT    CHECK (paused_until IS NULL OR paused_until GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    freq             TEXT    NOT NULL CHECK (length(freq) BETWEEN 1 AND 40 AND freq NOT GLOB '*[^a-z0-9_]*'),
    every_minutes    INTEGER CHECK (every_minutes IS NULL OR every_minutes BETWEEN 1 AND 527040),
    at_time          TEXT    CHECK (at_time IS NULL OR at_time GLOB '[0-2][0-9]:[0-5][0-9]'),
    weekdays         TEXT    CHECK (weekdays IS NULL OR (json_valid(weekdays) AND json_type(weekdays) = 'array')), -- [1..7], 1 = Monday
    month_day        INTEGER CHECK (month_day IS NULL OR month_day BETWEEN 0 AND 31),                                 -- 0 = the last day
    once_at          TEXT    CHECK (once_at IS NULL OR once_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    tz               TEXT    NOT NULL CHECK (length(tz) BETWEEN 1 AND 64),                                             -- 'org' or an IANA zone
    window_mode      TEXT    NOT NULL CHECK (window_mode IN ('global', 'none', 'custom')),
    window_days      TEXT    CHECK (window_days IS NULL OR (json_valid(window_days) AND json_type(window_days) = 'array')),
    window_from      TEXT    CHECK (window_from IS NULL OR window_from GLOB '[0-2][0-9]:[0-5][0-9]'),
    window_to        TEXT    CHECK (window_to IS NULL OR window_to GLOB '[0-2][0-9]:[0-5][0-9]'),
    next_due_at      TEXT    CHECK (next_due_at IS NULL OR next_due_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_due_at      TEXT    CHECK (last_due_at IS NULL OR last_due_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_run_id      TEXT    REFERENCES core_run (id) ON DELETE SET NULL,
    last_skip_reason TEXT    CHECK (last_skip_reason IS NULL OR length(last_skip_reason) BETWEEN 1 AND 300),
    last_skip_at     TEXT    CHECK (last_skip_at IS NULL OR last_skip_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by       TEXT    NOT NULL CHECK (length(updated_by) BETWEEN 1 AND 320), -- an email, or system
    updated_at       TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK (enabled = 1 OR next_due_at IS NULL),
    CHECK ((last_skip_reason IS NULL) = (last_skip_at IS NULL)),
    CHECK (window_mode = 'custom' OR (window_days IS NULL AND window_from IS NULL AND window_to IS NULL)),
    CHECK (window_mode <> 'custom' OR (window_days IS NOT NULL AND window_from IS NOT NULL AND window_to IS NOT NULL))
);

CREATE INDEX core_schedule_due_idx ON core_schedule (enabled, next_due_at);

CREATE INDEX core_schedule_last_run_idx ON core_schedule (last_run_id);

-- module auth-oidc

CREATE TABLE oidc_config (
    id            INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    issuer        TEXT    NOT NULL CHECK (issuer GLOB 'https://*' AND length(issuer) <= 2048),
    client_id     TEXT    NOT NULL CHECK (length(client_id) BETWEEN 1 AND 200),
    secret_id     TEXT    NOT NULL REFERENCES core_secret (id),
    secret_last4  TEXT    NOT NULL CHECK (length(secret_last4) = 4),
    scopes        TEXT    NOT NULL CHECK (length(scopes) BETWEEN 6 AND 700),
    groups_claim  TEXT    NOT NULL CHECK (length(groups_claim) BETWEEN 1 AND 64),
    default_role  TEXT    CHECK (default_role IS NULL OR default_role IN ('viewer', 'operator', 'admin')),
    role_map      TEXT    NOT NULL CHECK (json_valid(role_map) AND json_type(role_map) = 'array'),
    redirect_uri  TEXT    NOT NULL CHECK (length(redirect_uri) BETWEEN 1 AND 2048),
    updated_at    TEXT    NOT NULL
, ca_pem TEXT NOT NULL DEFAULT '' CHECK (length(ca_pem) <= 65536));

CREATE TABLE oidc_flow (
    state_hash    TEXT    NOT NULL PRIMARY KEY CHECK (length(state_hash) = 64),
    binding_hash  TEXT    NOT NULL CHECK (length(binding_hash) = 64),
    nonce         TEXT    NOT NULL CHECK (length(nonce) BETWEEN 32 AND 128),
    verifier      TEXT    NOT NULL CHECK (length(verifier) BETWEEN 43 AND 128),
    issuer        TEXT    NOT NULL,
    client_id     TEXT    NOT NULL,
    redirect_uri  TEXT    NOT NULL,
    created_at    TEXT    NOT NULL,
    expires_at    TEXT    NOT NULL
);

CREATE INDEX oidc_flow_created_idx ON oidc_flow (created_at);

-- module feeds

CREATE TABLE feeds_source (
    id              TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    builtin         INTEGER NOT NULL CHECK (builtin IN (0, 1)),
    name            TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 60),
    kind            TEXT    NOT NULL CHECK (kind IN ('vulnerabilities', 'ioc')),
    format          TEXT    NOT NULL CHECK (format IN ('json', 'csv', 'rss', 'stix', 'lines')),
    url             TEXT    NOT NULL CHECK (length(url) BETWEEN 1 AND 500),
    default_url     TEXT    CHECK ((builtin = 1) = (default_url IS NOT NULL)),
    enabled         INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    auth_type       TEXT    NOT NULL DEFAULT 'none' CHECK (auth_type IN ('none', 'header', 'bearer', 'basic')),
    auth_header_name TEXT,
    auth_username   TEXT,
    secret_id       TEXT    REFERENCES core_secret (id),
    secret_last4    TEXT    CHECK (secret_last4 IS NULL OR length(secret_last4) = 4),
    parser          TEXT    CHECK (parser IS NULL OR json_valid(parser)),
    license         TEXT,
    created_at      TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_fetch      TEXT    CHECK (last_fetch IS NULL OR last_fetch GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_success    TEXT    CHECK (last_success IS NULL OR last_success GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    failures        INTEGER NOT NULL DEFAULT 0 CHECK (failures >= 0),
    records         INTEGER CHECK (records IS NULL OR records >= 0),
    status          TEXT    NOT NULL DEFAULT 'never' CHECK (status IN ('never', 'ok', 'error')),
    error           TEXT,
    etag            TEXT,
    last_modified   TEXT,
    catalog_version TEXT, rev INTEGER NOT NULL DEFAULT 0 CHECK (rev >= 0), answered_by TEXT, mirror_etag TEXT, mirror_last_modified TEXT, distro_packages TEXT CHECK (distro_packages IS NULL OR (json_valid(distro_packages) AND json_type(distro_packages) = 'array')), kev_copies TEXT, catalog_released TEXT, stale_watch_from TEXT, stale_alerted_at TEXT, stale_failed_since TEXT, stale_failed_checks INTEGER NOT NULL DEFAULT 0,
    CHECK (builtin = 1 OR parser IS NOT NULL),
    CHECK (secret_id IS NULL OR auth_type <> 'none')
);

CREATE TABLE feeds_ioc (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    type       TEXT NOT NULL CHECK (type IN ('ip', 'domain', 'url', 'hash')),
    value      TEXT NOT NULL CHECK (length(value) BETWEEN 1 AND 2000),
    first_seen TEXT NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    UNIQUE (type, value)
);

CREATE TABLE feeds_ioc_source (
    ioc_id     TEXT    NOT NULL REFERENCES feeds_ioc (id) ON DELETE CASCADE,
    source_id  TEXT    NOT NULL REFERENCES feeds_source (id) ON DELETE CASCADE,
    last_seen  TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    confidence REAL    NOT NULL CHECK (confidence >= 0 AND confidence <= 1),
    seen       INTEGER NOT NULL DEFAULT 1 CHECK (seen IN (0, 1)),
    PRIMARY KEY (ioc_id, source_id)
) WITHOUT ROWID;

CREATE TABLE feeds_fetch_log (
    id               TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    source_id        TEXT    NOT NULL REFERENCES feeds_source (id) ON DELETE CASCADE,
    started_at       TEXT    NOT NULL CHECK (started_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    finished_at      TEXT    CHECK (finished_at IS NULL OR finished_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    status           TEXT    NOT NULL CHECK (status IN ('ok', 'error')),
    records_accepted INTEGER NOT NULL DEFAULT 0 CHECK (records_accepted >= 0),
    records_rejected INTEGER NOT NULL DEFAULT 0 CHECK (records_rejected >= 0),
    reject_reasons   TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(reject_reasons) AND json_type(reject_reasons) = 'array'),
    error            TEXT,
    bytes            INTEGER CHECK (bytes IS NULL OR bytes >= 0),
    etag             TEXT,
    last_modified    TEXT
);

CREATE TABLE feeds_weekly_answer (
    key         TEXT NOT NULL PRIMARY KEY CHECK (length(key) BETWEEN 1 AND 500),
    answer      TEXT NOT NULL CHECK (answer IN ('have', 'not_relevant')),
    user_id     TEXT NOT NULL CHECK (length(user_id) > 0),
    answered_at TEXT NOT NULL CHECK (answered_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, device_added INTEGER NOT NULL DEFAULT 0 CHECK (device_added IN (0, 1)), device_id TEXT CHECK (device_id IS NULL OR length(device_id) BETWEEN 1 AND 64), have_since TEXT CHECK (have_since IS NULL OR have_since GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'));

CREATE TABLE feeds_epss (
    cve        TEXT    NOT NULL PRIMARY KEY CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 32),
    epss       REAL    NOT NULL CHECK (epss BETWEEN 0 AND 1),
    percentile REAL    NOT NULL CHECK (percentile BETWEEN 0 AND 1),
    gen        INTEGER NOT NULL
) WITHOUT ROWID;

CREATE TABLE feeds_epss_baseline (
    id    INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    url   TEXT    NOT NULL CHECK (length(url) <= 2048),
    count INTEGER NOT NULL CHECK (count >= 0)
, score_date TEXT CHECK (score_date IS NULL OR score_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'));

CREATE TABLE feeds_epss_hist (
    cve  TEXT NOT NULL CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 32),
    day  TEXT NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    epss REAL NOT NULL CHECK (epss BETWEEN 0 AND 1),
    PRIMARY KEY (cve, day)
) WITHOUT ROWID;

CREATE TABLE feeds_cve (
    cve               TEXT NOT NULL PRIMARY KEY CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 32),
    published         TEXT CHECK (published IS NULL OR published GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    modified          TEXT CHECK (modified IS NULL OR modified GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    nvd_status        TEXT CHECK (nvd_status IS NULL OR length(nvd_status) BETWEEN 1 AND 40),
    nvd_at            TEXT CHECK (nvd_at IS NULL OR nvd_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    record_at         TEXT CHECK (record_at IS NULL OR record_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    title             TEXT NOT NULL DEFAULT '' CHECK (length(title) <= 500),
    description       TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 4000),
    cwe               TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(cwe) AND json_type(cwe) = 'array'),
    solution          TEXT NOT NULL DEFAULT '' CHECK (length(solution) <= 4000),
    workaround        TEXT NOT NULL DEFAULT '' CHECK (length(workaround) <= 4000),
    ssvc_exploitation TEXT CHECK (ssvc_exploitation IS NULL OR (length(ssvc_exploitation) BETWEEN 1 AND 40 AND ssvc_exploitation NOT GLOB '*[^a-z0-9_]*')),
    ssvc_automatable  TEXT CHECK (ssvc_automatable IS NULL OR (length(ssvc_automatable) BETWEEN 1 AND 40 AND ssvc_automatable NOT GLOB '*[^a-z0-9_]*')),
    ssvc_impact       TEXT CHECK (ssvc_impact IS NULL OR (length(ssvc_impact) BETWEEN 1 AND 40 AND ssvc_impact NOT GLOB '*[^a-z0-9_]*')),
    updated_at        TEXT NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE feeds_cve_metric (
    cve     TEXT NOT NULL REFERENCES feeds_cve (cve) ON DELETE CASCADE,
    source  TEXT NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    version TEXT NOT NULL CHECK (version IN ('4.0', '3.1', '3.0', '2.0')),
    score   REAL NOT NULL CHECK (score BETWEEN 0 AND 10),
    vector  TEXT NOT NULL CHECK (length(vector) <= 200 AND (vector GLOB 'CVSS:[34].[01]/*' OR vector GLOB 'AV:[LAN]/*')),
    PRIMARY KEY (cve, source, version)
) WITHOUT ROWID;

CREATE TABLE feeds_cve_range (
    id           INTEGER NOT NULL PRIMARY KEY,
    cve          TEXT    NOT NULL REFERENCES feeds_cve (cve) ON DELETE CASCADE,
    origin       TEXT    NOT NULL CHECK (length(origin) BETWEEN 1 AND 40 AND origin NOT GLOB '*[^a-z0-9_]*'),
    part         TEXT    NOT NULL CHECK (length(part) <= 1),
    vendor       TEXT    NOT NULL CHECK (length(vendor) <= 200),
    product      TEXT    NOT NULL CHECK (length(product) <= 200),
    cpe          TEXT    NOT NULL CHECK (cpe = '' OR (cpe GLOB 'cpe:2.3:*' AND length(cpe) <= 500)),
    start_incl   TEXT    NOT NULL CHECK (length(start_incl) <= 100),
    start_excl   TEXT    NOT NULL CHECK (length(start_excl) <= 100),
    end_incl     TEXT    NOT NULL CHECK (length(end_incl) <= 100),
    end_excl     TEXT    NOT NULL CHECK (length(end_excl) <= 100),
    fixed        TEXT    NOT NULL DEFAULT '' CHECK (length(fixed) <= 100),
    version_type TEXT    NOT NULL DEFAULT '' CHECK (length(version_type) <= 40),
    default_status TEXT  NOT NULL DEFAULT '' CHECK (default_status IN ('', 'affected', 'unaffected', 'unknown')),
    platforms    TEXT    CHECK (platforms IS NULL OR (json_valid(platforms) AND json_type(platforms) = 'array'))
);

CREATE TABLE feeds_cve_ref (
    cve    TEXT NOT NULL REFERENCES feeds_cve (cve) ON DELETE CASCADE,
    url    TEXT NOT NULL CHECK (length(url) BETWEEN 9 AND 500 AND (url GLOB 'https://*' OR url GLOB 'http://*')),
    tags   TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(tags) AND json_type(tags) = 'array'),
    source TEXT NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    PRIMARY KEY (cve, url)
) WITHOUT ROWID;

CREATE TABLE feeds_kev (
    cve             TEXT    NOT NULL REFERENCES feeds_cve (cve) ON DELETE CASCADE,
    list            TEXT    NOT NULL CHECK (length(list) BETWEEN 1 AND 110),
    source_id       TEXT    NOT NULL REFERENCES feeds_source (id) ON DELETE CASCADE,
    vendor          TEXT    NOT NULL,
    product         TEXT    NOT NULL,
    name            TEXT    NOT NULL,
    description     TEXT    NOT NULL DEFAULT '',
    required_action TEXT    NOT NULL DEFAULT '',
    links           TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(links) AND json_type(links) = 'array'),
    date_added      TEXT    NOT NULL CHECK (date_added GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    due_date        TEXT    CHECK (due_date IS NULL OR due_date GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    ransomware      INTEGER NOT NULL DEFAULT 0 CHECK (ransomware IN (0, 1)),
    announced_at    TEXT    CHECK (announced_at IS NULL OR announced_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at      TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    PRIMARY KEY (cve, list)
);

CREATE TABLE feeds_signal (
    cve        TEXT    NOT NULL CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 32),
    kind       TEXT    NOT NULL CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    source     TEXT    NOT NULL CHECK (length(source) BETWEEN 1 AND 96),
    first_seen TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    stored_at  TEXT    NOT NULL CHECK (stored_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    qualifies  INTEGER NOT NULL CHECK (qualifies IN (0, 1)),
    url        TEXT    NOT NULL DEFAULT '' CHECK (length(url) <= 500),
    detail     TEXT    CHECK (detail IS NULL OR (json_valid(detail) AND json_type(detail) = 'object' AND length(detail) <= 500)),
    PRIMARY KEY (cve, kind, source)
) WITHOUT ROWID;

CREATE TABLE feeds_nvd_cursor (
    selector   TEXT    NOT NULL PRIMARY KEY CHECK (length(selector) BETWEEN 1 AND 40 AND selector NOT GLOB '*[^a-z0-9_]*'),
    url        TEXT    NOT NULL CHECK (length(url) <= 2048),
    mode       TEXT    NOT NULL CHECK (mode IN ('fill', 'walk', 'update', 'done')),
    win_from   TEXT    NOT NULL,
    win_to     TEXT    NOT NULL,
    until      TEXT    NOT NULL,
    next_index INTEGER NOT NULL CHECK (next_index >= 0),
    total      INTEGER NOT NULL CHECK (total >= 0)
) WITHOUT ROWID;

CREATE TABLE feeds_winrel (
    build   INTEGER NOT NULL CHECK (build BETWEEN 10240 AND 99999),
    server  INTEGER NOT NULL CHECK (server IN (0, 1)),
    product TEXT    NOT NULL UNIQUE CHECK (length(product) BETWEEN 1 AND 60 AND product GLOB 'windows_*'),
    display TEXT    NOT NULL CHECK (length(display) BETWEEN 1 AND 60),
    line    INTEGER NOT NULL CHECK (line BETWEEN 10240 AND 99999),
    ga      TEXT    NOT NULL CHECK (ga GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    ga_rev  INTEGER NOT NULL CHECK (ga_rev BETWEEN 0 AND 999999),
    PRIMARY KEY (build, server)
) WITHOUT ROWID;

CREATE TABLE feeds_winrel_update (
    build  INTEGER NOT NULL CHECK (build BETWEEN 10240 AND 99999),
    server INTEGER NOT NULL CHECK (server IN (0, 1)),
    rev    INTEGER NOT NULL CHECK (rev BETWEEN 1 AND 999999),
    kb     TEXT    NOT NULL CHECK (kb = '' OR (kb GLOB 'KB[0-9]*' AND kb NOT GLOB 'KB*[^0-9]*' AND length(kb) BETWEEN 8 AND 10)),
    day    TEXT    NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), hotpatch INTEGER NOT NULL DEFAULT 0 CHECK (hotpatch IN (0, 1)),
    PRIMARY KEY (build, server, rev)
) WITHOUT ROWID;

CREATE TABLE "feeds_distro_fix" (
    source_id     TEXT    NOT NULL REFERENCES feeds_source (id) ON DELETE CASCADE,
    distro        TEXT    NOT NULL CHECK (distro IN ('ubuntu', 'debian', 'alpine')),
    release       TEXT    NOT NULL CHECK (length(release) BETWEEN 1 AND 8 AND release NOT GLOB '*[^0-9.]*'),
    package       TEXT    NOT NULL CHECK (length(package) BETWEEN 1 AND 100),
    cve           TEXT    NOT NULL CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 32),
    status        TEXT    NOT NULL CHECK (status IN ('fixed', 'not_affected', 'open')),
    fixed_version TEXT    CHECK ((status = 'fixed') = (fixed_version IS NOT NULL) AND (fixed_version IS NULL OR length(fixed_version) BETWEEN 1 AND 100)),
    pro           INTEGER NOT NULL DEFAULT 0 CHECK (pro IN (0, 1)),
    PRIMARY KEY (source_id, distro, release, package, cve)
);

CREATE UNIQUE INDEX feeds_source_name_uq ON feeds_source (lower(name));

CREATE INDEX feeds_source_kind_idx ON feeds_source (kind, enabled);

CREATE INDEX feeds_ioc_last_seen_idx ON feeds_ioc (last_seen);

CREATE INDEX feeds_ioc_source_src_idx ON feeds_ioc_source (source_id);

CREATE INDEX feeds_fetch_log_source_idx ON feeds_fetch_log (source_id, started_at DESC);

CREATE INDEX feeds_distro_fix_cve_idx ON feeds_distro_fix (cve);

CREATE INDEX feeds_distro_fix_package_idx ON feeds_distro_fix (distro, package);

CREATE INDEX feeds_cve_published_idx ON feeds_cve (published);

CREATE INDEX feeds_cve_range_cve_idx ON feeds_cve_range (cve);

CREATE INDEX feeds_cve_range_product_idx ON feeds_cve_range (vendor, product, cpe);

CREATE INDEX feeds_kev_list_idx ON feeds_kev (list, date_added DESC, cve DESC);

CREATE INDEX feeds_kev_source_idx ON feeds_kev (source_id);

CREATE INDEX feeds_kev_announced_idx ON feeds_kev (announced_at, cve) WHERE announced_at IS NOT NULL;

CREATE INDEX feeds_signal_kind_idx ON feeds_signal (kind, qualifies, cve);

CREATE INDEX feeds_signal_source_idx ON feeds_signal (source, kind);

-- module inventory

CREATE TABLE inv_observation (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    asset_id   TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    field      TEXT NOT NULL CHECK (field IN ('kind', 'hostname', 'mac', 'vendor', 'model', 'os')),
    value      TEXT NOT NULL CHECK (length(value) BETWEEN 1 AND 253),
    source     TEXT NOT NULL CHECK (source IN ('manual', 'declared', 'agent', 'snmp', 'nmap', 'passive', 'scan')),
    confidence REAL NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    seen_at    TEXT NOT NULL CHECK (seen_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    evidence   TEXT
, first_seen TEXT);

CREATE TABLE inv_service (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    asset_id   TEXT    NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    port       INTEGER NOT NULL CHECK (port BETWEEN 1 AND 65535),
    proto      TEXT    NOT NULL CHECK (proto IN ('tcp', 'udp')),
    name       TEXT    NOT NULL CHECK (length(name) <= 100),
    product    TEXT    CHECK (product IS NULL OR length(product) <= 200),
    version    TEXT    CHECK (version IS NULL OR length(version) <= 100),
    source     TEXT    NOT NULL CHECK (source IN ('manual', 'agent', 'snmp', 'nmap', 'passive', 'scan')),
    confidence REAL    NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    seen_at    TEXT    NOT NULL CHECK (seen_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, detail TEXT CHECK (detail IS NULL OR length(detail) <= 200),
    -- when the source last read the port's name, product and version (a scan with version detection, an agent's report); NULL: only
    -- found open. A scan that only finds open ports leaves it; the weekly version read picks the ports read longest ago by it.
    read_at TEXT CHECK (read_at IS NULL OR read_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    -- the address a network scan found the port on: '' for the device's main address (inv_asset.ip) and for sources that read the
    -- whole machine (an agent), else the id of one of its other addresses (inv_asset_address). A scan of one address replaces only
    -- the ports it found there, so two interfaces of one device never replace each other's ports.
    addr_id TEXT NOT NULL DEFAULT '' CHECK (length(addr_id) <= 96));

CREATE TABLE inv_software (
    id               TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    asset_id         TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    product_key      TEXT NOT NULL CHECK (length(product_key) BETWEEN 1 AND 400),
    line             TEXT NOT NULL DEFAULT '' CHECK (length(line) <= 20),
    display          TEXT NOT NULL CHECK (length(display) BETWEEN 1 AND 200),
    vendor           TEXT NOT NULL CHECK (length(vendor) BETWEEN 1 AND 200),
    product          TEXT NOT NULL CHECK (length(product) BETWEEN 1 AND 200),
    cpe              TEXT CHECK (cpe IS NULL OR length(cpe) <= 500),
    version          TEXT CHECK (version IS NULL OR length(version) BETWEEN 1 AND 100),
    pkg_version      TEXT CHECK (pkg_version IS NULL OR length(pkg_version) BETWEEN 1 AND 100),
    pkg_source       TEXT CHECK (pkg_source IS NULL OR length(pkg_source) BETWEEN 1 AND 100),
    packaged         INTEGER NOT NULL DEFAULT 0 CHECK (packaged IN (0, 1)),
    source           TEXT NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    set_by           TEXT CHECK (set_by IS NULL OR length(set_by) BETWEEN 1 AND 320),
    confidence       REAL NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    seen_at          TEXT NOT NULL CHECK (seen_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    differs          INTEGER NOT NULL DEFAULT 0 CHECK (differs IN (0, 1)),
    state            TEXT NOT NULL DEFAULT 'present' CHECK (state IN ('present', 'not_installed', 'removed')),
    not_installed_by TEXT CHECK (not_installed_by IS NULL OR length(not_installed_by) BETWEEN 1 AND 320),
    not_installed_at TEXT CHECK (not_installed_at IS NULL OR not_installed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    first_seen       TEXT NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen        TEXT NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    removed_at       TEXT CHECK (removed_at IS NULL OR removed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((state = 'removed') = (removed_at IS NOT NULL)),
    CHECK (state <> 'not_installed' OR not_installed_at IS NOT NULL) -- a removed line keeps a person's mark: it holds when the software is read again
);

CREATE TABLE inv_software_reading (
    software_id TEXT NOT NULL REFERENCES inv_software (id) ON DELETE CASCADE,
    source      TEXT NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    instance    TEXT NOT NULL DEFAULT '' CHECK (length(instance) <= 120),
    display     TEXT NOT NULL CHECK (length(display) BETWEEN 1 AND 200),
    version     TEXT CHECK (version IS NULL OR length(version) BETWEEN 1 AND 100),
    pkg_version TEXT CHECK (pkg_version IS NULL OR length(pkg_version) BETWEEN 1 AND 100),
    pkg_source  TEXT CHECK (pkg_source IS NULL OR length(pkg_source) BETWEEN 1 AND 100),
    packaged    INTEGER NOT NULL DEFAULT 0 CHECK (packaged IN (0, 1)),
    cpe         TEXT CHECK (cpe IS NULL OR length(cpe) <= 500),
    confidence  REAL NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    set_by      TEXT CHECK (set_by IS NULL OR (source = 'manual' AND length(set_by) BETWEEN 1 AND 320)),
    first_seen  TEXT NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    seen_at     TEXT NOT NULL CHECK (seen_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    -- the address a network scan read it at: '' for the device's main address and for sources that read the whole machine, else the
    -- id of one of the device's other addresses (inv_asset_address), as inv_service.addr_id
    addr_id     TEXT NOT NULL DEFAULT '' CHECK (length(addr_id) <= 96),
    PRIMARY KEY (software_id, source, instance, addr_id)
) WITHOUT ROWID;

CREATE TABLE inv_software_event (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    asset_id     TEXT NOT NULL CHECK (length(asset_id) BETWEEN 1 AND 96),
    software_id  TEXT NOT NULL CHECK (length(software_id) BETWEEN 1 AND 96),
    product_key  TEXT NOT NULL CHECK (length(product_key) BETWEEN 1 AND 400),
    display      TEXT NOT NULL CHECK (length(display) BETWEEN 1 AND 200),
    ts           TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    kind         TEXT NOT NULL CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    from_version TEXT CHECK (from_version IS NULL OR length(from_version) <= 100),
    to_version   TEXT CHECK (to_version IS NULL OR length(to_version) <= 100),
    source       TEXT CHECK (source IS NULL OR length(source) BETWEEN 1 AND 40),
    actor        TEXT CHECK (actor IS NULL OR length(actor) BETWEEN 1 AND 320)
);

CREATE TABLE inv_setting (
    key        TEXT NOT NULL PRIMARY KEY CHECK (key IN ('lan_ranges', 'active', 'fragile_kinds', 'regular_scan_kinds', 'scope', 'notify_new')),
    value      TEXT NOT NULL CHECK (json_valid(value)),
    updated_at TEXT NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by TEXT NOT NULL CHECK (length(updated_by) BETWEEN 1 AND 320)
);

CREATE TABLE "inv_asset" (
    id             TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ip             TEXT    CHECK (ip IS NULL OR length(ip) BETWEEN 7 AND 15),
    mac            TEXT    CHECK (mac IS NULL OR length(mac) = 17),
    hostname       TEXT    CHECK (hostname IS NULL OR length(hostname) BETWEEN 1 AND 253),
    kind           TEXT    NOT NULL DEFAULT 'unknown' CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    vendor         TEXT    CHECK (vendor IS NULL OR length(vendor) <= 200),
    model          TEXT    CHECK (model IS NULL OR length(model) <= 200),
    os             TEXT    CHECK (os IS NULL OR length(os) <= 200),
    vendor_obs_id  TEXT,
    model_obs_id   TEXT,
    os_obs_id      TEXT,
    kind_obs_id    TEXT,
    hostname_obs_id TEXT,
    mac_obs_id     TEXT,
    origin         TEXT    NOT NULL CHECK (origin IN ('discovered', 'manual')),
    approved       BOOLEAN NOT NULL DEFAULT 0 CHECK (approved IN (0, 1)),
    fragile        BOOLEAN NOT NULL DEFAULT 0 CHECK (fragile IN (0, 1)),
    fragile_manual BOOLEAN NOT NULL DEFAULT 0 CHECK (fragile_manual IN (0, 1)),
    regular_scan   TEXT    NOT NULL DEFAULT 'follow' CHECK (regular_scan IN ('follow', 'allow', 'never')),
    first_scan_at  TEXT    CHECK (first_scan_at IS NULL OR first_scan_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    suspicious     BOOLEAN NOT NULL DEFAULT 0 CHECK (suspicious IN (0, 1)),
    is_box         BOOLEAN NOT NULL DEFAULT 0 CHECK (is_box IN (0, 1)),
    notes          TEXT    CHECK (notes IS NULL OR length(notes) <= 2000),
    first_seen     TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen      TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    approved_at    TEXT    CHECK (approved_at IS NULL OR approved_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, agent_key TEXT CHECK (agent_key IS NULL OR length(agent_key) BETWEEN 3 AND 81), agent_ip TEXT CHECK (agent_ip IS NULL OR length(agent_ip) BETWEEN 7 AND 15), ip_confirmed_at TEXT, user_name TEXT CHECK (user_name IS NULL OR length(user_name) BETWEEN 1 AND 64), scan_source TEXT CHECK (scan_source IN ('on', 'off')), snmp_source TEXT CHECK (snmp_source IN ('on', 'off')), agent_source TEXT CHECK (agent_source IN ('on', 'off')), ignored_at TEXT, review_earned_at TEXT);

CREATE TABLE inv_asset_address (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    asset_id   TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    ip         TEXT CHECK (ip IS NULL OR length(ip) BETWEEN 7 AND 15),
    mac        TEXT CHECK (mac IS NULL OR length(mac) = 17),
    source     TEXT NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    first_seen TEXT NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK (ip IS NOT NULL OR mac IS NOT NULL)
);

CREATE TABLE inv_source (
    source     TEXT NOT NULL PRIMARY KEY CHECK (source IN ('agent', 'snmp', 'nmap', 'passive', 'scan')),
    first_seen TEXT NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE inv_separate (
    a          TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    b          TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    decided_by TEXT NOT NULL CHECK (length(decided_by) BETWEEN 1 AND 320),
    decided_at TEXT NOT NULL CHECK (decided_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    PRIMARY KEY (a, b),
    CHECK (a < b)
);

CREATE TABLE inv_hand_seen (
    asset_id   TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    mac        TEXT NOT NULL CHECK (length(mac) = 17),
    first_seen TEXT NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    PRIMARY KEY (asset_id, mac)
);

CREATE TABLE inv_detected_keep (
    asset_id TEXT NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    field    TEXT NOT NULL CHECK (field IN ('hostname', 'vendor', 'model', 'os', 'kind')),
    detected TEXT NOT NULL CHECK (length(detected) BETWEEN 1 AND 253),
    kept_at  TEXT NOT NULL,
    kept_by  TEXT,
    PRIMARY KEY (asset_id, field, detected)
) WITHOUT ROWID;

CREATE UNIQUE INDEX inv_observation_uq ON inv_observation (asset_id, field, source, value);

CREATE INDEX inv_observation_field_ix ON inv_observation (asset_id, field);

CREATE UNIQUE INDEX inv_service_uq ON inv_service (asset_id, port, proto, source, addr_id);

CREATE INDEX inv_service_asset_ix ON inv_service (asset_id);

CREATE UNIQUE INDEX inv_software_line_uq ON inv_software (asset_id, product_key, line);

CREATE INDEX inv_software_state_ix ON inv_software (asset_id, state);

CREATE INDEX inv_software_product_ix ON inv_software (product_key);

CREATE INDEX inv_software_event_asset_ix ON inv_software_event (asset_id, ts);

CREATE INDEX inv_software_event_line_ix ON inv_software_event (software_id, ts);

CREATE UNIQUE INDEX inv_asset_ip_uq ON inv_asset (ip) WHERE ip IS NOT NULL;

CREATE UNIQUE INDEX inv_asset_box_uq ON inv_asset (is_box) WHERE is_box = 1;

CREATE INDEX inv_asset_hostname_ix ON inv_asset (lower(hostname)) WHERE hostname IS NOT NULL;

CREATE UNIQUE INDEX inv_asset_mac_uq ON inv_asset (mac) WHERE mac IS NOT NULL;

CREATE INDEX inv_asset_kind_ix ON inv_asset (kind);

CREATE INDEX inv_asset_approved_ix ON inv_asset (approved);

CREATE INDEX inv_asset_last_seen_ix ON inv_asset (last_seen);

CREATE UNIQUE INDEX inv_asset_agent_key ON inv_asset (agent_key) WHERE agent_key IS NOT NULL;

CREATE INDEX inv_software_reading_source_ix ON inv_software_reading (source, software_id);

CREATE INDEX inv_observation_mac_ix ON inv_observation (value) WHERE field = 'mac';

CREATE INDEX inv_separate_b_ix ON inv_separate (b);

CREATE INDEX inv_hand_seen_mac_ix ON inv_hand_seen (mac);

CREATE UNIQUE INDEX inv_asset_address_ip_uq ON inv_asset_address (ip) WHERE ip IS NOT NULL;

CREATE UNIQUE INDEX inv_asset_address_mac_uq ON inv_asset_address (mac) WHERE mac IS NOT NULL;

CREATE INDEX inv_asset_address_asset_ix ON inv_asset_address (asset_id);

CREATE TRIGGER inv_observation_append_only BEFORE UPDATE ON inv_observation
WHEN NEW.id IS NOT OLD.id OR NEW.asset_id IS NOT OLD.asset_id OR NEW.field IS NOT OLD.field OR NEW.value IS NOT OLD.value
  OR NEW.source IS NOT OLD.source OR NEW.evidence IS NOT OLD.evidence
BEGIN
    SELECT RAISE(ABORT, 'inv_observation is append-only');
END;

CREATE TRIGGER inv_software_event_append_only BEFORE UPDATE ON inv_software_event
WHEN NEW.id IS NOT OLD.id OR NEW.product_key IS NOT OLD.product_key OR NEW.display IS NOT OLD.display OR NEW.ts IS NOT OLD.ts
  OR NEW.kind IS NOT OLD.kind OR NEW.from_version IS NOT OLD.from_version OR NEW.to_version IS NOT OLD.to_version
  OR NEW.source IS NOT OLD.source OR NEW.actor IS NOT OLD.actor
BEGIN
    SELECT RAISE(ABORT, 'inv_software_event is append-only');
END;

-- module agent-intake

CREATE TABLE intake_agent_tokens (
    id            TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name          TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 256),
    kind          TEXT NOT NULL DEFAULT 'osquery' CHECK (kind IN ('osquery')),
    token_hash    TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64),
    last4         TEXT NOT NULL CHECK (length(last4) = 4),
    created_at    TEXT NOT NULL,
    expires_at    TEXT,
    last_received TEXT
, created_by TEXT CHECK (created_by IS NULL OR length(created_by) BETWEEN 1 AND 256), first_enrolled_at TEXT,
    -- the device a person made the token for (the device page's agent row: Create agent token, then Show setup); NULL for a token
    -- made for any machine. The device's own agent row shows it until a machine enrols with it.
    device_id     TEXT REFERENCES inv_asset (id) ON DELETE SET NULL);

CREATE INDEX intake_agent_tokens_device_idx ON intake_agent_tokens (device_id) WHERE device_id IS NOT NULL;

CREATE TABLE intake_osquery_nodes (
    id              TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    token_id        TEXT NOT NULL REFERENCES intake_agent_tokens (id) ON DELETE CASCADE,
    node_key_hash   TEXT NOT NULL UNIQUE CHECK (length(node_key_hash) = 64),
    host_identifier TEXT NOT NULL CHECK (length(host_identifier) BETWEEN 1 AND 1024),
    hostname        TEXT,
    platform        TEXT,
    osquery_version TEXT,
    enrolled_at     TEXT NOT NULL,
    last_seen       TEXT NOT NULL,
    last_result_at  TEXT,
    bound_ip        TEXT,
    bound_mac       TEXT, reported TEXT NOT NULL DEFAULT '' CHECK (length(reported) <= 64), approved_at TEXT, kernel TEXT NOT NULL DEFAULT '' CHECK (length(kernel) <= 100), win_name TEXT NOT NULL DEFAULT '' CHECK (length(win_name) <= 200), win_version TEXT NOT NULL DEFAULT '' CHECK (length(win_version) <= 40), win_target TEXT NOT NULL DEFAULT '' CHECK (win_target IN ('', 'x64', 'x86', 'arm64')), report_asked_at TEXT, software_taken_at TEXT, os_taken_at TEXT, last_call_at TEXT,
    -- The node's rhythm (nodestate.go NodeHealth): call_every_s is how often it was told to call (osquery: the config refresh the
    -- install scripts set; the package reporter: its hourly run), call_gap_s its own smoothed gap between config fetches (NULL until it has
    -- fetched its config twice), report_every_s the longest interval of the schedule the box last gave it without its speed-ups (it delivers results at least that often).
    call_every_s    INTEGER NOT NULL DEFAULT 300 CHECK (call_every_s BETWEEN 60 AND 86400),
    call_gap_s      INTEGER CHECK (call_gap_s IS NULL OR call_gap_s BETWEEN 1 AND 172800),
    report_every_s  INTEGER NOT NULL DEFAULT 3600 CHECK (report_every_s BETWEEN 60 AND 86400),
    UNIQUE (token_id, host_identifier)
);

CREATE TABLE intake_wazuh (
    id                 INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    url                TEXT    NOT NULL CHECK (url GLOB 'https://*' AND length(url) <= 200),
    username           TEXT    NOT NULL CHECK (length(username) BETWEEN 1 AND 64),
    secret_id          TEXT    NOT NULL REFERENCES core_secret (id),
    password_last4     TEXT    NOT NULL CHECK (length(password_last4) IN (0, 4)),
    tls_pin            TEXT    NOT NULL CHECK (tls_pin = 'system' OR (length(tls_pin) = 64 AND tls_pin NOT GLOB '*[^0-9a-f]*')),
    tls_pin_first_seen TEXT    NOT NULL,
    generation         INTEGER NOT NULL DEFAULT 1,
    status             TEXT    NOT NULL DEFAULT 'never' CHECK (status IN ('never', 'connected', 'error')),
    last_sync          TEXT,
    next_pull          TEXT,
    agents             INTEGER NOT NULL DEFAULT 0 CHECK (agents >= 0),
    packages           INTEGER NOT NULL DEFAULT 0 CHECK (packages >= 0),
    error              TEXT    CHECK (error IS NULL OR length(error) <= 500),
    resume_after       TEXT    CHECK (resume_after IS NULL OR (length(resume_after) BETWEEN 3 AND 10 AND resume_after NOT GLOB '*[^0-9]*')),
    pass_packages      INTEGER NOT NULL DEFAULT 0 CHECK (pass_packages >= 0),
    updated_at         TEXT    NOT NULL
);

CREATE TABLE intake_prune_clock (
    id       INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    last_run TEXT    NOT NULL
);

CREATE TABLE intake_wazuh_agent (
    agent_id   TEXT    NOT NULL PRIMARY KEY CHECK (length(agent_id) BETWEEN 3 AND 10 AND agent_id NOT GLOB '*[^0-9]*'),
    generation INTEGER NOT NULL,
    ip         TEXT    NOT NULL CHECK (length(ip) BETWEEN 7 AND 15),
    mac        TEXT    NOT NULL DEFAULT '' CHECK (mac = '' OR length(mac) = 17),
    seen_at    TEXT    NOT NULL
);

CREATE INDEX intake_osquery_nodes_seen_idx ON intake_osquery_nodes (last_seen);

-- module sensor-active

CREATE TABLE sa_all_ports (
    asset_id     TEXT NOT NULL PRIMARY KEY CHECK (length(asset_id) BETWEEN 1 AND 96),
    last_at      TEXT CHECK (last_at IS NULL OR last_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    -- retry: one failure, tried again in the next window (still due); the others make the device due a week after last_at
    outcome      TEXT CHECK (outcome IS NULL OR outcome IN ('done', 'not_eligible', 'answers_everywhere', 'retry', 'failed'))
);

CREATE TABLE "sa_probe" (
    id           INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    time         TEXT    NOT NULL CHECK (time GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    run_id       TEXT    REFERENCES core_run (id) ON DELETE SET NULL,
    shape        TEXT    NOT NULL CHECK (shape IN ('sweep', 'normal', 'gentle', 'versions', 'gentle_titles', 'snmp', 'external', 'external_full', 'external_disruptive', 'all_ports', 'extra_ports', 'port_versions')),
    rate         INTEGER NOT NULL CHECK (rate BETWEEN 1 AND 1000),
    hosts        INTEGER NOT NULL CHECK (hosts BETWEEN 1 AND 64),
    flags        TEXT    NOT NULL CHECK (length(flags) BETWEEN 1 AND 16384),
    targets      TEXT    NOT NULL CHECK (length(targets) BETWEEN 7 AND 1100),
    result       TEXT    NOT NULL CHECK (length(result) <= 200)
);

CREATE TABLE sa_snmp_device (
    asset_id          TEXT    NOT NULL PRIMARY KEY REFERENCES inv_asset (id) ON DELETE CASCADE CHECK (length(asset_id) BETWEEN 1 AND 96),
    read_from         TEXT    NOT NULL CHECK (length(read_from) BETWEEN 7 AND 15),
    read_from_default INTEGER NOT NULL CHECK (read_from_default IN (0, 1)),
    version           TEXT    NOT NULL CHECK (version IN ('v2c', 'v3')),
    username          TEXT    CHECK (username IS NULL OR length(username) BETWEEN 1 AND 64),
    auth              TEXT    CHECK (auth IS NULL OR auth IN ('sha', 'sha256')),
    priv              TEXT    CHECK (priv IS NULL OR priv = 'aes128'),
    secret_id         TEXT    NOT NULL CHECK (length(secret_id) BETWEEN 1 AND 96),
    secret_last4      TEXT    NOT NULL DEFAULT '' CHECK (length(secret_last4) <= 4),
    priv_secret_id    TEXT    CHECK (priv_secret_id IS NULL OR length(priv_secret_id) BETWEEN 1 AND 96),
    priv_last4        TEXT    NOT NULL DEFAULT '' CHECK (length(priv_last4) <= 4),
    port              INTEGER CHECK (port IS NULL OR port BETWEEN 1 AND 65535),
    created_at        TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at        TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_checked_at   TEXT    CHECK (last_checked_at IS NULL OR last_checked_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_status       TEXT    CHECK (last_status IS NULL OR last_status IN ('ok', 'no_answer', 'auth_failed', 'unknown_user', 'error')),
    last_answer_at    TEXT    CHECK (last_answer_at IS NULL OR last_answer_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    answer            TEXT    CHECK (answer IS NULL OR (json_valid(answer) AND length(answer) <= 6000)),
    CHECK ((version = 'v2c' AND username IS NULL AND auth IS NULL AND priv IS NULL AND priv_secret_id IS NULL)
        OR (version = 'v3' AND username IS NOT NULL AND auth IS NOT NULL AND (priv IS NULL) = (priv_secret_id IS NULL)))
);

CREATE TABLE sa_snmp_notice (
    id   INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    at   TEXT    NOT NULL CHECK (at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    text TEXT    NOT NULL CHECK (length(text) BETWEEN 1 AND 2000)
);

CREATE INDEX sa_probe_time_ix ON sa_probe (time);

CREATE INDEX sa_probe_run_ix ON sa_probe (run_id);

-- module honeypot

CREATE TABLE hp_tokens (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    type       TEXT NOT NULL CHECK (type IN ('file', 'credential', 'url', 'dns')),
    name       TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 64),
    value      TEXT NOT NULL CHECK (length(value) BETWEEN 1 AND 300),
    secret_id  TEXT REFERENCES core_secret (id),
    plant_at   TEXT NOT NULL CHECK (length(plant_at) BETWEEN 1 AND 120),
    created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((type = 'credential') = (secret_id IS NOT NULL))
) STRICT;

CREATE TABLE hp_ignored_day (
    day   TEXT    NOT NULL PRIMARY KEY CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    count INTEGER NOT NULL CHECK (count >= 0)
) STRICT;

CREATE TABLE hp_trap_ips (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name       TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 15),
    ip         TEXT    NOT NULL UNIQUE CHECK (length(ip) BETWEEN 7 AND 15),
    preset     TEXT    NOT NULL CHECK (preset IN ('file_server', 'nas', 'printer', 'camera', 'linux', 'database', 'custom')),
    vendor     TEXT    CHECK (vendor IS NULL OR length(vendor) BETWEEN 1 AND 32),
    services   TEXT    NOT NULL CHECK (json_valid(services) AND json_type(services) = 'array'),
    enabled    INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    -- The last MAC the host gave the address (it derives it from the address and the vendor, so it is the same next time): a device
    -- row carrying it is a ghost of this Trap IP's own frames, never a machine on the address. NULL until the host says.
    mac        TEXT    CHECK (mac IS NULL OR length(mac) = 17),
    -- When the address last became a Trap IP that is on (added, switched on, moved); NULL = created_at. A device row the inventory
    -- made at the address or of its MAC after this is a ghost of the decoy and is forgotten; one from before is a real machine.
    enabled_at TEXT    CHECK (enabled_at IS NULL OR length(enabled_at) = 24),
    created_at TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
) STRICT;

CREATE TABLE "hp_config" (
    key        TEXT NOT NULL PRIMARY KEY CHECK (key IN ('applied', 'tail', 'https')),
    value      TEXT NOT NULL CHECK (json_valid(value)),
    updated_at TEXT NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by TEXT NOT NULL CHECK (length(updated_by) > 0)
) STRICT;

CREATE TABLE "hp_hits" (
    id             TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ts             TEXT    NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    kind           TEXT    NOT NULL CHECK (kind IN ('service', 'token', 'scan')),
    service        TEXT    CHECK (service IS NULL OR service IN ('smb', 'rdp', 'ssh', 'mssql', 'http', 'https', 'ftp', 'telnet', 'mysql',
                                                             'mongodb', 'redis', 'vnc', 'git', 'httpproxy', 'tcpbanner', 'tftp', 'ntp', 'sip')),
    label          TEXT    NOT NULL CHECK (length(label) <= 200),
    port           INTEGER CHECK (port IS NULL OR port BETWEEN 1 AND 65535),
    src_ip         TEXT    NOT NULL CHECK (length(src_ip) BETWEEN 7 AND 15),
    source_ip      TEXT    GENERATED ALWAYS AS (src_ip) VIRTUAL,
    is_test        INTEGER NOT NULL DEFAULT 0 CHECK (is_test IN (0, 1)),
    excerpt        TEXT    NOT NULL CHECK (length(excerpt) <= 1000),
    trap_ip        TEXT    NOT NULL CHECK (length(trap_ip) <= 400),
    trap_hostname  TEXT    NOT NULL CHECK (length(trap_hostname) <= 200),
    token_id       TEXT    CHECK (token_id IS NULL OR length(token_id) <= 96),
    events         TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(events)),
    conn_key       TEXT    UNIQUE CHECK (conn_key IS NULL OR length(conn_key) = 64),
    conn_count     INTEGER NOT NULL DEFAULT 1 CHECK (conn_count >= 1),
    handshake      INTEGER NOT NULL DEFAULT 1 CHECK (handshake IN (0, 1))
) STRICT;

CREATE UNIQUE INDEX hp_tokens_name_ux ON hp_tokens (type, lower(name));

CREATE INDEX hp_hits_ts_ix ON hp_hits (ts DESC);

CREATE INDEX hp_hits_src_ix ON hp_hits (src_ip);

CREATE INDEX hp_hits_token_ix ON hp_hits (token_id) WHERE token_id IS NOT NULL;

-- module findings

CREATE TABLE fnd_finding (
    id             TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    asset_id       TEXT    NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    cve            TEXT    NOT NULL
        CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*'
               AND substr(cve, 5) NOT GLOB '*[^0-9-]*'
               AND cve NOT GLOB 'CVE-[0-9][0-9][0-9][0-9]-*-*'),
    -- The software line the CVE is on; NULL only for a safe-check hit on a device with no line for that product.
    software_id    TEXT    REFERENCES inv_software (id) ON DELETE SET NULL,
    -- A. detection
    detected       INTEGER NOT NULL CHECK (detected IN (0, 1)),
    basis          TEXT    NOT NULL CHECK (length(basis) BETWEEN 1 AND 40 AND basis NOT GLOB '*[^a-z0-9_]*'),
    verified       TEXT    NOT NULL CHECK (verified IN ('no', 'device', 'scan', 'person')),
    range_origin   TEXT    NOT NULL CHECK (length(range_origin) BETWEEN 1 AND 40 AND range_origin NOT GLOB '*[^a-z0-9_]*'),
    matched_version TEXT   CHECK (matched_version IS NULL OR length(matched_version) BETWEEN 1 AND 200),
    fix_kind       TEXT    NOT NULL CHECK (length(fix_kind) BETWEEN 1 AND 40 AND fix_kind NOT GLOB '*[^a-z0-9_]*'),
    fix_version    TEXT    CHECK (fix_version IS NULL OR length(fix_version) BETWEEN 1 AND 200),
    fix_ref        TEXT    CHECK (fix_ref IS NULL OR length(fix_ref) BETWEEN 1 AND 200),
    fix_key        TEXT    NOT NULL CHECK (length(fix_key) BETWEEN 1 AND 400),
    evidence       TEXT    CHECK (evidence IS NULL OR (json_valid(evidence) AND json_type(evidence) = 'object')),
    -- B. handling
    state          TEXT    NOT NULL CHECK (state IN ('open', 'handled')),
    resolution     TEXT    CHECK (resolution IS NULL OR resolution IN ('patched', 'mitigated', 'accepted', 'false_positive', 'not_relevant')),
    via            TEXT    CHECK (via IS NULL OR (length(via) BETWEEN 1 AND 40 AND via NOT GLOB '*[^a-z0-9_]*')),
    resolved_by    TEXT    CHECK (resolved_by IS NULL OR length(resolved_by) BETWEEN 1 AND 320),
    resolved_at    TEXT    CHECK (resolved_at IS NULL OR resolved_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    note           TEXT    CHECK (note IS NULL OR length(note) <= 600),
    -- The last day of a risk acceptance (UTC); the finding reopens by itself once that day is over everywhere.
    accepted_until TEXT    CHECK (accepted_until IS NULL OR accepted_until GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    -- via version_moved: the version that was affected and the version installed now ("6.24 -> 7.23").
    from_version   TEXT    CHECK (from_version IS NULL OR length(from_version) BETWEEN 1 AND 200),
    to_version     TEXT    CHECK (to_version IS NULL OR length(to_version) BETWEEN 1 AND 200),
    -- C. urgency: 1 under attack here, 2 exploited, 3 public exploit, 4 critical on an edge device, 5 update recommended
    urgency        INTEGER NOT NULL CHECK (urgency BETWEEN 1 AND 5),
    urgency_at     TEXT    NOT NULL CHECK (urgency_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    first_seen     TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen      TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at     TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((state = 'open') = (resolution IS NULL)),
    CHECK ((state = 'open') = (via IS NULL)),
    CHECK ((state = 'open') = (resolved_by IS NULL)),
    CHECK ((state = 'open') = (resolved_at IS NULL)),
    CHECK ((resolution IS 'accepted') = (accepted_until IS NOT NULL)),
    CHECK ((via IS 'version_moved') = (from_version IS NOT NULL AND to_version IS NOT NULL AND from_version <> to_version)),
    CHECK (via IS 'version_moved' OR (from_version IS NULL AND to_version IS NULL))
);

CREATE UNIQUE INDEX fnd_finding_line_uq ON fnd_finding (asset_id, cve, ifnull(software_id, ''));

CREATE INDEX fnd_finding_state_urgency_ix ON fnd_finding (state, urgency);

CREATE INDEX fnd_finding_asset_state_ix ON fnd_finding (asset_id, state);

CREATE INDEX fnd_finding_cve_ix ON fnd_finding (cve);

CREATE INDEX fnd_finding_software_ix ON fnd_finding (software_id);

CREATE INDEX fnd_finding_fix_ix ON fnd_finding (fix_key, state);

CREATE INDEX fnd_finding_resolved_ix ON fnd_finding (state, resolved_at);

CREATE TABLE fnd_finding_event (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    finding_id TEXT    NOT NULL REFERENCES fnd_finding (id) ON DELETE CASCADE,
    ts         TEXT    NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    actor      TEXT    NOT NULL CHECK (length(actor) BETWEEN 1 AND 320),
    kind       TEXT    NOT NULL CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    detail     TEXT    CHECK (detail IS NULL OR (json_valid(detail) AND json_type(detail) = 'object'))
);

CREATE INDEX fnd_finding_event_finding_ix ON fnd_finding_event (finding_id, id);

CREATE INDEX fnd_finding_event_ts_ix ON fnd_finding_event (ts, kind);

CREATE TRIGGER fnd_finding_event_no_update BEFORE UPDATE ON fnd_finding_event
BEGIN
    SELECT RAISE(ABORT, 'fnd_finding_event is append-only');
END;

CREATE TABLE fnd_question (
    id          TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    asset_id    TEXT    NOT NULL REFERENCES inv_asset (id) ON DELETE CASCADE,
    software_id TEXT    REFERENCES inv_software (id) ON DELETE CASCADE,
    cve         TEXT    CHECK (cve IS NULL OR (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 32)),
    kind        TEXT    NOT NULL CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    detail      TEXT    CHECK (detail IS NULL OR (json_valid(detail) AND json_type(detail) = 'object')),
    cves        INTEGER NOT NULL CHECK (cves >= 1),
    asked_at    TEXT    NOT NULL CHECK (asked_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    answer      TEXT    CHECK (answer IS NULL OR length(answer) BETWEEN 1 AND 200),
    answered_by TEXT    CHECK (answered_by IS NULL OR length(answered_by) BETWEEN 1 AND 320),
    answered_at TEXT    CHECK (answered_at IS NULL OR answered_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((answer IS NULL) = (answered_by IS NULL) AND (answer IS NULL) = (answered_at IS NULL))
);

CREATE UNIQUE INDEX fnd_question_uq ON fnd_question (asset_id, ifnull(software_id, ''), ifnull(cve, ''), kind);

CREATE INDEX fnd_question_software_ix ON fnd_question (software_id);

CREATE TABLE fnd_reach_run (
    id          INTEGER PRIMARY KEY,
    ran_at      TEXT    NOT NULL CHECK (ran_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    stamp       TEXT    NOT NULL CHECK (length(stamp) <= 4000),
    total       INTEGER NOT NULL CHECK (total >= 0),
    counts      TEXT    NOT NULL CHECK (json_valid(counts) AND json_type(counts) = 'object'),
    unreachable TEXT    NOT NULL CHECK (json_valid(unreachable) AND json_type(unreachable) = 'object'),
    added       TEXT    NOT NULL CHECK (json_valid(added) AND json_type(added) = 'object')
);

-- module mitigation

CREATE TABLE mit_applied (
    finding_id TEXT NOT NULL REFERENCES fnd_finding (id) ON DELETE CASCADE,
    item       TEXT NOT NULL CHECK (item IN ('patch', 'workaround', 'fortigate', 'mikrotik', 'generic')),
    ts         TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    user       TEXT NOT NULL CHECK (length(user) BETWEEN 1 AND 320),
    PRIMARY KEY (finding_id, item)
) WITHOUT ROWID;

CREATE TABLE mit_ai_output (
    finding_id  TEXT NOT NULL REFERENCES fnd_finding (id) ON DELETE CASCADE,
    skill       TEXT NOT NULL CHECK (skill IN ('explain', 'mitigation-config')),
    payload     TEXT NOT NULL CHECK (json_valid(payload) AND json_type(payload) = 'object'),
    model       TEXT NOT NULL CHECK (length(model) <= 200),
    profile     TEXT CHECK (profile IS NULL OR length(profile) <= 200),
    created_at  TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    activity_id TEXT CHECK (activity_id IS NULL OR length(activity_id) BETWEEN 1 AND 96),
    PRIMARY KEY (finding_id, skill)
) WITHOUT ROWID;

CREATE TABLE mit_pack (
    cve          TEXT NOT NULL PRIMARY KEY CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*'),
    -- patch, workaround, firewall[], checklist, sources[] and the optional recheck block
    body         TEXT NOT NULL CHECK (json_valid(body) AND json_type(body) = 'object'),
    compromise   TEXT CHECK (compromise IS NULL OR (json_valid(compromise) AND json_type(compromise) = 'object')),
    confirmed_by TEXT NOT NULL CHECK (length(confirmed_by) BETWEEN 1 AND 320),
    confirmed_at TEXT NOT NULL CHECK (confirmed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*'),
    drafted_with TEXT NOT NULL CHECK (length(drafted_with) BETWEEN 1 AND 200),
    pack_version TEXT NOT NULL CHECK (length(pack_version) BETWEEN 1 AND 64)
) WITHOUT ROWID;

CREATE TABLE mit_pack_state (
    id           INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    version      TEXT    NOT NULL CHECK (length(version) BETWEEN 1 AND 64),
    installed_at TEXT    NOT NULL CHECK (installed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

-- module notify

CREATE TABLE notify_channel (
    type                TEXT    NOT NULL PRIMARY KEY CHECK (type IN ('telegram', 'slack', 'zalo', 'zalo-personal', 'email', 'webhook')),
    configured          BOOLEAN NOT NULL DEFAULT 0 CHECK (configured IN (0, 1)),
    enabled             BOOLEAN NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
    fields              TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(fields)),
    secret_id           TEXT    REFERENCES core_secret (id),
    secret_last4        TEXT    CHECK (secret_last4 IS NULL OR length(secret_last4) = 4),
    app_token_secret_id TEXT    REFERENCES core_secret (id),
    app_token_last4     TEXT    CHECK (app_token_last4 IS NULL OR length(app_token_last4) = 4),
    bot_token_secret_id TEXT    REFERENCES core_secret (id),
    bot_token_last4     TEXT    CHECK (bot_token_last4 IS NULL OR length(bot_token_last4) = 4),
    min_severity        TEXT    NOT NULL DEFAULT 'medium' CHECK (min_severity IN ('critical', 'high', 'medium', 'low')),
    approvals           BOOLEAN NOT NULL DEFAULT 0 CHECK (approvals IN (0, 1)),
    last_test           TEXT    CHECK (last_test IS NULL OR json_valid(last_test)),
    rev                 INTEGER NOT NULL DEFAULT 1,  -- bumped on every change that affects sending: invalidates the cached sender
    updated_at          TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, url_secret_id TEXT REFERENCES core_secret (id), url_last4 TEXT CHECK (url_last4 IS NULL OR length(url_last4) = 4));

CREATE TABLE notify_approver (
    channel_type TEXT NOT NULL REFERENCES notify_channel (type) ON DELETE CASCADE,
    user_id      TEXT NOT NULL CHECK (length(user_id) BETWEEN 1 AND 96),
    address      TEXT NOT NULL CHECK (length(address) BETWEEN 1 AND 254), name TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (channel_type, user_id)
);

CREATE TABLE notify_setting (
    key        TEXT NOT NULL PRIMARY KEY CHECK (key IN ('quiet', 'grouping')),
    value      TEXT NOT NULL CHECK (json_valid(value)),
    updated_at TEXT NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by TEXT NOT NULL CHECK (length(updated_by) > 0)
);

CREATE TABLE notify_incident (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    kind       TEXT    NOT NULL CHECK (length(kind) BETWEEN 1 AND 40 AND kind NOT GLOB '*[^a-z0-9_]*'),
    title      TEXT    NOT NULL CHECK (length(title) BETWEEN 1 AND 400),
    link       TEXT    NOT NULL CHECK (length(link) BETWEEN 1 AND 400),
    severity   TEXT    NOT NULL CHECK (severity IN ('critical', 'high', 'medium', 'low', 'info')),
    what       TEXT    NOT NULL CHECK (length(what) <= 4000),
    action     TEXT    NOT NULL CHECK (length(action) <= 4000),
    first_seen TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    count      INTEGER NOT NULL DEFAULT 1 CHECK (count >= 1),
    status     TEXT    NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'acknowledged', 'resolved')),
    handled_by TEXT,
    handled_at TEXT    CHECK (handled_at IS NULL OR handled_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    note       TEXT    CHECK (note IS NULL OR length(note) <= 2000),
    dedupe_key TEXT    NOT NULL CHECK (length(dedupe_key) = 64)
, attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt IN (0, 1)), unsent TEXT CHECK (unsent IS NULL OR length(unsent) BETWEEN 1 AND 40), unsent_floor TEXT CHECK (unsent_floor IS NULL OR unsent_floor IN ('critical', 'high', 'medium', 'low')), unsent_channel TEXT CHECK (unsent_channel IS NULL OR unsent_channel IN ('telegram', 'slack', 'zalo', 'zalo-personal', 'email', 'webhook')), resolved_reason TEXT CHECK (resolved_reason IS NULL OR length(resolved_reason) <= 500), active_at TEXT CHECK (active_at IS NULL OR active_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), first_run INTEGER NOT NULL DEFAULT 0 CHECK (first_run IN (0, 1)), summary_id TEXT CHECK (summary_id IS NULL OR length(summary_id) <= 64));

CREATE TABLE notify_incident_device (
    incident_id TEXT NOT NULL REFERENCES notify_incident (id) ON DELETE CASCADE,
    asset_id    TEXT NOT NULL CHECK (length(asset_id) BETWEEN 1 AND 96),
    name        TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 253),
    PRIMARY KEY (incident_id, asset_id)
);

CREATE TABLE notify_notice (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 128),
    event      TEXT NOT NULL DEFAULT '' CHECK (length(event) <= 40 AND event NOT GLOB '*[^a-z0-9_]*'),
    created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    product    TEXT NOT NULL CHECK (length(product) <= 300),
    cves       TEXT NOT NULL CHECK (json_valid(cves))
);

CREATE TABLE notify_notice_finding (
    notice_id  TEXT NOT NULL REFERENCES notify_notice (id) ON DELETE CASCADE,
    finding_id TEXT NOT NULL CHECK (length(finding_id) BETWEEN 1 AND 96),
    -- the urgency layer the finding was told at (1 most urgent .. 4); 0 when the notice did not tell an urgency. A finding is told again
    -- only at a more urgent layer than every one it was told at.
    layer      INTEGER NOT NULL DEFAULT 0 CHECK (layer BETWEEN 0 AND 5),
    PRIMARY KEY (notice_id, finding_id)
);

CREATE TABLE notify_send (
    id      TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    kind    TEXT    NOT NULL CHECK (kind IN ('incident', 'vuln', 'approval')),
    ref_id  TEXT    NOT NULL CHECK (length(ref_id) BETWEEN 1 AND 128),
    channel TEXT    NOT NULL CHECK (channel IN ('telegram', 'slack', 'zalo', 'zalo-personal', 'email', 'webhook')),
    "to"    TEXT    NOT NULL CHECK (length("to") <= 600),
    at      TEXT    NOT NULL CHECK (at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    ok      BOOLEAN NOT NULL CHECK (ok IN (0, 1)),
    error   TEXT    CHECK (error IS NULL OR length(error) <= 1000),
    what    TEXT    NOT NULL CHECK (length(what) <= 400),
    link    TEXT    NOT NULL CHECK (length(link) <= 400),
    message TEXT    NOT NULL CHECK (json_valid(message) AND length(message) <= 16384),
    -- Who the message went to when it went to one person (an approver's address): a resend goes to the same person, not to the alert list.
    recipient TEXT  CHECK (recipient IS NULL OR length(recipient) BETWEEN 1 AND 254)
, delayed INTEGER NOT NULL DEFAULT 0 CHECK (delayed IN (0, 1)));

CREATE TABLE notify_send_notice (
    send_id   TEXT NOT NULL REFERENCES notify_send (id) ON DELETE CASCADE,
    notice_id TEXT NOT NULL REFERENCES notify_notice (id) ON DELETE CASCADE,
    PRIMARY KEY (send_id, notice_id)
);

CREATE TABLE notify_pending (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    channel    TEXT NOT NULL CHECK (channel IN ('telegram', 'slack', 'zalo', 'zalo-personal', 'email', 'webhook')),
    notice_id  TEXT NOT NULL CHECK (length(notice_id) BETWEEN 1 AND 128),
    notice     TEXT NOT NULL CHECK (json_valid(notice) AND length(notice) <= 65536),
    reason     TEXT NOT NULL CHECK (reason IN ('now', 'group', 'quiet', 'settle')),
    due_at     TEXT NOT NULL CHECK (due_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    state      TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'claimed', 'sending')),
    claimed_at TEXT CHECK (claimed_at IS NULL OR claimed_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts BETWEEN 0 AND 100));

CREATE TABLE notify_tg_button (
    request_id TEXT NOT NULL PRIMARY KEY CHECK (length(request_id) BETWEEN 1 AND 50),
    nonce_hash TEXT NOT NULL CHECK (length(nonce_hash) = 64),
    expires_at TEXT NOT NULL CHECK (expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, message_id INTEGER CHECK (message_id IS NULL OR message_id BETWEEN 1 AND 9007199254740992), chat_id TEXT CHECK (chat_id IS NULL OR length(chat_id) BETWEEN 1 AND 21), state TEXT NOT NULL DEFAULT 'none' CHECK (state IN ('none', 'shown', 'remove', 'removed')), tries INTEGER NOT NULL DEFAULT 0 CHECK (tries BETWEEN 0 AND 5));

CREATE TABLE notify_slack_button (
    request_id TEXT NOT NULL CHECK (length(request_id) BETWEEN 1 AND 128),
    channel_id TEXT NOT NULL CHECK (length(channel_id) BETWEEN 9 AND 13),
    ts         TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]'),
    expires_at TEXT NOT NULL CHECK (expires_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), state TEXT NOT NULL DEFAULT 'shown' CHECK (state IN ('shown', 'remove', 'removed')), outcome TEXT CHECK (outcome IS NULL OR outcome IN ('approved', 'rejected', 'expired', 'cancelled', 'ended')), tries INTEGER NOT NULL DEFAULT 0 CHECK (tries BETWEEN 0 AND 5),
    PRIMARY KEY (request_id, channel_id, ts)
);

CREATE TABLE notify_slack_team (
    id      INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    rev     INTEGER NOT NULL,
    team_id TEXT    NOT NULL CHECK (length(team_id) BETWEEN 7 AND 21)
);

CREATE TABLE notify_slack_final (
    request_id TEXT NOT NULL PRIMARY KEY CHECK (length(request_id) BETWEEN 1 AND 128),
    outcome    TEXT NOT NULL CHECK (outcome IN ('approved', 'rejected', 'expired', 'cancelled', 'ended')),
    at         TEXT NOT NULL CHECK (at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE notify_box (
    id                   INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    first_run_at         TEXT    NOT NULL CHECK (first_run_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    discovery_told_at    TEXT    CHECK (discovery_told_at IS NULL OR discovery_told_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    discovery_told_count INTEGER NOT NULL DEFAULT 0 CHECK (discovery_told_count >= 0)
);

CREATE INDEX notify_incident_status_ix ON notify_incident (status, last_seen DESC);

CREATE UNIQUE INDEX notify_incident_open_uq ON notify_incident (dedupe_key) WHERE status <> 'resolved';

CREATE INDEX notify_notice_created_ix ON notify_notice (created_at);

CREATE INDEX notify_notice_finding_ix ON notify_notice_finding (finding_id);

CREATE INDEX notify_send_at_ix ON notify_send (at DESC);

CREATE INDEX notify_send_ref_ix ON notify_send (kind, ref_id);

CREATE INDEX notify_send_notice_ix ON notify_send_notice (notice_id);

CREATE UNIQUE INDEX notify_pending_uq ON notify_pending (channel, notice_id);

CREATE INDEX notify_pending_state_ix ON notify_pending (state, channel);

CREATE INDEX notify_tg_button_expires_ix ON notify_tg_button (expires_at);

CREATE INDEX notify_tg_button_state_ix ON notify_tg_button (state, expires_at);

CREATE INDEX notify_slack_button_expires_ix ON notify_slack_button (expires_at);

CREATE INDEX notify_slack_button_state_ix ON notify_slack_button (state, expires_at);

CREATE INDEX notify_slack_final_at_ix ON notify_slack_final (at);

CREATE UNIQUE INDEX notify_approver_address_ux ON notify_approver (channel_type, address);

-- module sensor-passive

CREATE TABLE sp_sensor (
    id            TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name          TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 253),
    interface     TEXT    CHECK (interface IS NULL OR length(interface) BETWEEN 1 AND 15),
    span          INTEGER NOT NULL DEFAULT 0 CHECK (span IN (0, 1)),
    version       TEXT    CHECK (version IS NULL OR length(version) <= 64),
    last_seen     TEXT    CHECK (last_seen IS NULL OR last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    devices_seen  INTEGER NOT NULL DEFAULT 0 CHECK (devices_seen >= 0)
) STRICT;

CREATE TABLE sp_span_stat (
    sensor_id       TEXT    NOT NULL PRIMARY KEY REFERENCES sp_sensor (id) ON DELETE CASCADE,
    packets_per_s   INTEGER NOT NULL CHECK (packets_per_s >= 0),
    other_macs      INTEGER NOT NULL CHECK (other_macs >= 0),
    last_packet_at  TEXT    CHECK (last_packet_at IS NULL OR last_packet_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    measured_at     TEXT    NOT NULL CHECK (measured_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
) STRICT;

CREATE TABLE sp_seq (
    sensor_id  TEXT    NOT NULL REFERENCES sp_sensor (id) ON DELETE CASCADE,
    epoch      TEXT    NOT NULL DEFAULT 'local' CHECK (length(epoch) BETWEEN 1 AND 64),
    last_seq   INTEGER NOT NULL CHECK (last_seq >= 0),
    PRIMARY KEY (sensor_id, epoch)
) STRICT;

-- module response

CREATE TABLE resp_settings (
    id         INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    value      TEXT    NOT NULL CHECK (json_valid(value)),
    updated_at TEXT    NOT NULL
);

CREATE TABLE resp_plans (
    id           TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    finding_id   TEXT NOT NULL,
    cve          TEXT NOT NULL,
    asset_id     TEXT NOT NULL,
    asset_name   TEXT NOT NULL,
    generated_at TEXT NOT NULL,
    model        TEXT NOT NULL,
    profile      TEXT NOT NULL,
    path         TEXT NOT NULL,
    reads        TEXT NOT NULL CHECK (json_valid(reads)),
    steps        TEXT NOT NULL CHECK (json_valid(steps))
);

CREATE TABLE resp_catalog (
    id             TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    builtin        BOOLEAN NOT NULL CHECK (builtin IN (0, 1)),
    pack           TEXT    NOT NULL CHECK (length(pack) BETWEEN 1 AND 60),
    kind           TEXT    NOT NULL CHECK (kind IN ('box', 'device')),
    name           TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 100),
    description    TEXT    NOT NULL,
    connection_id  TEXT,
    tool           TEXT,
    rollback_tool  TEXT,
    run            TEXT    NOT NULL CHECK (json_valid(run)),
    rollback       TEXT    NOT NULL CHECK (json_valid(rollback)),
    verify         TEXT    NOT NULL CHECK (json_valid(verify)),
    risk           TEXT    NOT NULL CHECK (risk IN ('low', 'medium', 'high')),
    enabled        BOOLEAN NOT NULL CHECK (enabled IN (0, 1)),
    ai_may_propose BOOLEAN NOT NULL CHECK (ai_may_propose IN (0, 1)),
    position       INTEGER NOT NULL
, precheck TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(precheck)), precheck_refuse TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(precheck_refuse) AND json_type(precheck_refuse) = 'array'), precheck_expect TEXT NOT NULL DEFAULT '' CHECK (length(precheck_expect) <= 80));

CREATE TABLE resp_rules (
    seq          INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    id           TEXT    NOT NULL UNIQUE CHECK (length(id) BETWEEN 1 AND 96),
    name         TEXT    NOT NULL,
    enabled      BOOLEAN NOT NULL CHECK (enabled IN (0, 1)),
    live         BOOLEAN NOT NULL DEFAULT 0 CHECK (live IN (0, 1)),
    trigger      TEXT    NOT NULL CHECK (trigger IN ('honeypot', 'ioc_connection', 'finding', 'unknown_device', 'log_threshold', 'new_port', 'schedule', 'manual')),
    match        TEXT    NOT NULL CHECK (match IN ('all', 'any')),
    conditions   TEXT    NOT NULL CHECK (json_valid(conditions)),
    actions      TEXT    NOT NULL CHECK (json_valid(actions)),
    pre_approved BOOLEAN NOT NULL DEFAULT 0 CHECK (pre_approved IN (0, 1)),
    max_per_hour INTEGER NOT NULL CHECK (max_per_hour BETWEEN 1 AND 100),
    schedule_min INTEGER CHECK (schedule_min IS NULL OR schedule_min BETWEEN 15 AND 10080),
    template_id  TEXT,
    last_fired   TEXT
);

CREATE TABLE resp_allowlist (
    value TEXT NOT NULL PRIMARY KEY CHECK (length(value) BETWEEN 1 AND 260),
    label TEXT NOT NULL CHECK (length(label) <= 80)
);

CREATE TABLE resp_blocklist (
    id              INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    token_hash      TEXT    NOT NULL CHECK (length(token_hash) = 64),
    secret_id       TEXT    NOT NULL REFERENCES core_secret (id),
    token_last4     TEXT    NOT NULL CHECK (length(token_last4) = 4),
    last_fetch_at   TEXT,
    last_fetch_from TEXT
);

CREATE TABLE resp_block_entries (
    value      TEXT NOT NULL,
    request_id TEXT NOT NULL,
    item_id    TEXT NOT NULL,
    source     TEXT NOT NULL,
    reason     TEXT NOT NULL,
    added_at   TEXT NOT NULL,
    expires_at TEXT,
    PRIMARY KEY (request_id, item_id)
);

CREATE TABLE resp_done (
    rule_id  TEXT NOT NULL,
    event_id TEXT NOT NULL,
    at       TEXT NOT NULL,
    PRIMARY KEY (rule_id, event_id)
);

CREATE TABLE resp_ai_notes (
    id         TEXT NOT NULL PRIMARY KEY,
    ts         TEXT NOT NULL,
    kind       TEXT NOT NULL CHECK (kind IN ('suggestion', 'digest')),
    title      TEXT NOT NULL,
    why        TEXT NOT NULL,
    confidence REAL NOT NULL,
    action_id  TEXT NOT NULL,
    target     TEXT NOT NULL,
    evidence   TEXT NOT NULL CHECK (json_valid(evidence))
);

CREATE TABLE resp_hints (
    id           TEXT NOT NULL PRIMARY KEY,
    ts           TEXT NOT NULL,
    kind         TEXT NOT NULL CHECK (kind IN ('rule', 'memory')),
    text         TEXT NOT NULL,
    from_request TEXT NOT NULL
);

CREATE TABLE resp_events (
    seq         INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    id          TEXT    NOT NULL UNIQUE CHECK (length(id) BETWEEN 1 AND 160),
    trigger     TEXT    NOT NULL CHECK (trigger IN ('honeypot', 'ioc_connection', 'finding', 'unknown_device', 'log_threshold', 'new_port', 'schedule', 'manual')),
    ts          TEXT    NOT NULL,
    summary     TEXT    NOT NULL,
    fields      TEXT    NOT NULL CHECK (json_valid(fields)),
    device_kind TEXT,
    asset_id    TEXT,
    finding_id  TEXT,
    cve         TEXT,
    processed   BOOLEAN NOT NULL DEFAULT 0 CHECK (processed IN (0, 1))
);

CREATE TABLE resp_log (
    seq       INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    id        TEXT    NOT NULL UNIQUE CHECK (length(id) BETWEEN 1 AND 96),
    ts        TEXT    NOT NULL,
    kind      TEXT    NOT NULL CHECK (kind IN ('rule_fired', 'proposal', 'request', 'approved', 'rejected', 'executed', 'rolled_back', 'ttl_removed', 'refused', 'expired', 'failed', 'settings', 'emergency_stop', 'blocklist_token', 'dry_run', 'simulated', 'deduped', 'breaker', 'ai_note')),
    actor     TEXT    NOT NULL CHECK (length(actor) BETWEEN 1 AND 320),
    detail    TEXT    NOT NULL CHECK (length(detail) <= 1500),
    prev_hash TEXT    NOT NULL CHECK (length(prev_hash) = 64),
    hash      TEXT    NOT NULL CHECK (length(hash) = 64)
);

CREATE TABLE resp_tokens (
    -- link: SHA-256 (hex) of the 16 byte token id inside the token v1.<id>.<mac>; code: the code hash of spec 7.1
    token_hash TEXT NOT NULL PRIMARY KEY CHECK (length(token_hash) = 64),
    kind       TEXT NOT NULL CHECK (kind IN ('link', 'code')),
    -- code only: the decision the code stands for (an "A-" or an "R-" code); a link is decided on the page
    decision   TEXT CHECK (decision IN ('approve', 'reject')),
    action_id  TEXT NOT NULL,
    user_id    TEXT NOT NULL,
    address    TEXT NOT NULL,
    channel    TEXT NOT NULL,
    -- link only: the id of the key that signed it (notify names it)
    key_id     TEXT,
    expires_at TEXT NOT NULL,
    used_at    TEXT,
    CHECK ((kind = 'link' AND channel IN ('email', 'zalo') AND decision IS NULL AND key_id IS NOT NULL) OR (kind = 'code' AND channel = 'zalo-personal' AND decision IS NOT NULL AND key_id IS NULL))
);

CREATE TABLE resp_identity (
    user_id   TEXT NOT NULL,
    channel   TEXT NOT NULL CHECK (channel IN ('email', 'slack', 'telegram', 'zalo', 'zalo-personal')),
    address   TEXT NOT NULL CHECK (length(address) BETWEEN 1 AND 320),
    linked_at TEXT NOT NULL,
    PRIMARY KEY (user_id, channel)
);

CREATE TABLE resp_link_codes (
    user_id    TEXT NOT NULL,
    channel    TEXT NOT NULL CHECK (channel IN ('email', 'slack', 'telegram', 'zalo', 'zalo-personal')),
    address    TEXT NOT NULL CHECK (length(address) BETWEEN 1 AND 320),
    code_hash  TEXT NOT NULL CHECK (length(code_hash) = 64),
    expires_at TEXT NOT NULL,
    sent_at    TEXT NOT NULL,
    tries      INTEGER NOT NULL DEFAULT 0 CHECK (tries BETWEEN 0 AND 5),
    PRIMARY KEY (user_id, channel)
);

CREATE TABLE "resp_actions" (
    seq                INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    id                 TEXT    NOT NULL UNIQUE CHECK (length(id) BETWEEN 1 AND 96),
    source             TEXT    NOT NULL CHECK (source IN ('ai', 'rule', 'person')),
    proposal_id        TEXT    NOT NULL,
    rule_id            TEXT,
    rule_name          TEXT,
    trigger            TEXT,
    trigger_summary    TEXT,
    finding_id         TEXT,
    cve                TEXT,
    asset_id           TEXT,
    asset_name         TEXT    NOT NULL,
    title              TEXT    NOT NULL,
    risk               TEXT    NOT NULL CHECK (risk IN ('low', 'medium', 'high')),
    status             TEXT    NOT NULL CHECK (status IN ('pending', 'approved', 'rejected', 'expired', 'executed', 'failed', 'rolled_back')),
    requested_at       TEXT    NOT NULL,
    expires_at         TEXT    NOT NULL,
    decided_at         TEXT,
    requires_approvals INTEGER NOT NULL CHECK (requires_approvals IN (1, 2)),
    two_because        TEXT,
    approvals          TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(approvals)),
    sent_to            TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(sent_to)),
    note               TEXT,
    pre_approved       BOOLEAN NOT NULL DEFAULT 0 CHECK (pre_approved IN (0, 1)),
    ai                 TEXT    CHECK (ai IS NULL OR json_valid(ai)),
    items              TEXT    NOT NULL CHECK (json_valid(items))
);

CREATE INDEX resp_plans_finding_ix ON resp_plans (finding_id);

CREATE INDEX resp_block_entries_value_ix ON resp_block_entries (value);

CREATE INDEX resp_events_trigger_ix ON resp_events (trigger, ts DESC);

CREATE INDEX resp_events_processed_ix ON resp_events (processed, seq);

CREATE INDEX resp_tokens_action ON resp_tokens (action_id);

CREATE INDEX resp_tokens_code ON resp_tokens (channel, address) WHERE kind = 'code' AND used_at IS NULL;

CREATE INDEX resp_actions_status_ix ON resp_actions (status, requested_at);

CREATE INDEX resp_actions_proposal_ix ON resp_actions (proposal_id);

CREATE INDEX resp_actions_rule_ix ON resp_actions (rule_id, requested_at);

CREATE TRIGGER resp_log_no_update BEFORE UPDATE ON resp_log
BEGIN
    SELECT RAISE(ABORT, 'resp_log is append-only');
END;

CREATE TRIGGER resp_log_no_delete BEFORE DELETE ON resp_log
BEGIN
    SELECT RAISE(ABORT, 'resp_log is append-only');
END;

CREATE TRIGGER resp_log_no_replace BEFORE INSERT ON resp_log
WHEN EXISTS (SELECT 1 FROM resp_log WHERE id = NEW.id OR seq = NEW.seq)
BEGIN
    SELECT RAISE(ABORT, 'resp_log is append-only');
END;

-- module exposure

CREATE TABLE exp_target (
    id           TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    parent_id    TEXT    REFERENCES exp_target (id) ON DELETE SET NULL,
    kind         TEXT    NOT NULL CHECK (kind IN ('domain', 'ip')),
    value        TEXT    NOT NULL UNIQUE CHECK (length(value) BETWEEN 1 AND 253),
    -- person: typed in; box: a public IP the box found as its own egress address; discovered: a name found under a domain target
    origin       TEXT    NOT NULL CHECK (origin IN ('person', 'box', 'discovered')),
    -- domains: self scans only this name, all this name and every name found under it, selected this name and the chosen names
    scope_mode   TEXT    CHECK ((kind = 'ip' AND scope_mode IS NULL) OR (kind = 'domain' AND scope_mode IS NOT NULL AND scope_mode IN ('self', 'all', 'selected'))),
    enabled      INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    method       TEXT    CHECK (method IS NULL OR (kind = 'domain' AND method = 'dns_txt') OR (kind = 'ip' AND method = 'box_egress')),
    -- domain: the value in the TXT record vedette-verify=<token> (public in DNS); IP: ''
    token        TEXT    NOT NULL CHECK ((kind = 'domain' AND length(token) = 16) OR (kind = 'ip' AND token = '')),
    verified_at  TEXT    CHECK (verified_at IS NULL OR verified_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    -- {at, ok, message}
    last_check   TEXT    CHECK (last_check IS NULL OR (json_valid(last_check) AND json_type(last_check) = 'object')),
    -- an IP typed in by a person: the token its proof file carries, and how it was proved
    ip_token     TEXT    CHECK (ip_token IS NULL OR (kind = 'ip' AND origin = 'person' AND length(ip_token) = 16)),
    proof_method TEXT    CHECK (proof_method IS NULL OR (kind = 'ip' AND origin = 'person' AND proof_method IN ('ip_file', 'ip_ptr'))),
    created_at   TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK (parent_id IS NULL OR (kind = 'domain' AND parent_id <> id))
);

CREATE INDEX exp_target_parent_idx ON exp_target (parent_id);

CREATE TABLE exp_consent (
    target_id  TEXT    NOT NULL REFERENCES exp_target (id) ON DELETE CASCADE,
    kind       TEXT    NOT NULL CHECK (kind IN ('commitment', 'terms')),
    version    TEXT    NOT NULL CHECK (length(version) BETWEEN 1 AND 40),
    text       TEXT    NOT NULL CHECK (length(text) BETWEEN 1 AND 10000),
    by_name    TEXT    NOT NULL CHECK (length(by_name) BETWEEN 1 AND 320),
    user_id    TEXT    CHECK (user_id IS NULL OR length(user_id) BETWEEN 1 AND 96),
    method     TEXT    CHECK (method IS NULL OR method IN ('app', 'email', 'sso')),
    disruptive INTEGER NOT NULL DEFAULT 0 CHECK (disruptive IN (0, 1) AND (disruptive = 0 OR kind = 'terms')),
    at         TEXT    NOT NULL CHECK (at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    PRIMARY KEY (target_id, kind)
) WITHOUT ROWID;

CREATE TABLE exp_host (
    id              TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    target_id       TEXT    NOT NULL REFERENCES exp_target (id) ON DELETE CASCADE,
    name            TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 253),
    -- ct | dns | mx | ns | wordlist | person (exposure.HostSource)
    source          TEXT    NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    selected        INTEGER NOT NULL DEFAULT 0 CHECK (selected IN (0, 1)),
    child_target_id TEXT    REFERENCES exp_target (id) ON DELETE SET NULL,
    cname           TEXT    CHECK (cname IS NULL OR length(cname) BETWEEN 1 AND 253),
    first_seen      TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen       TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    UNIQUE (target_id, name),
    CHECK (first_seen <= last_seen)
);

CREATE INDEX exp_host_child_idx ON exp_host (child_target_id);

CREATE TABLE exp_address (
    id         INTEGER NOT NULL PRIMARY KEY,
    host_id    TEXT    REFERENCES exp_host (id) ON DELETE CASCADE,
    target_id  TEXT    NOT NULL REFERENCES exp_target (id) ON DELETE CASCADE,
    ip         TEXT    NOT NULL CHECK (length(ip) BETWEEN 2 AND 45),
    family     TEXT    NOT NULL CHECK (family IN ('ipv4', 'ipv6')),
    -- box: this box's own current IP; public: any other public address; private: never dialed
    class      TEXT    NOT NULL CHECK (class IN ('box', 'public', 'private')),
    first_seen TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen  TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK (first_seen <= last_seen)
);

CREATE UNIQUE INDEX exp_address_key ON exp_address (target_id, ifnull(host_id, ''), ip);

CREATE INDEX exp_address_host_idx ON exp_address (host_id);

CREATE TABLE exp_service (
    id          TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    target_id   TEXT    NOT NULL REFERENCES exp_target (id) ON DELETE CASCADE,
    ip          TEXT    NOT NULL CHECK (length(ip) BETWEEN 2 AND 45),
    port        INTEGER NOT NULL CHECK (port BETWEEN 1 AND 65535),
    proto       TEXT    NOT NULL CHECK (proto IN ('tcp', 'udp')),
    name        TEXT    NOT NULL DEFAULT '' CHECK (length(name) <= 100),
    product     TEXT    NOT NULL DEFAULT '' CHECK (length(product) <= 500),
    version     TEXT    NOT NULL DEFAULT '' CHECK (length(version) <= 500),
    cpe         TEXT    NOT NULL DEFAULT '' CHECK (length(cpe) <= 500),
    title       TEXT    NOT NULL DEFAULT '' CHECK (length(title) <= 500),
    -- {names, issuer, expires_at}: the TLS certificate the service showed
    cert        TEXT    CHECK (cert IS NULL OR (json_valid(cert) AND json_type(cert) = 'object')),
    is_web      INTEGER NOT NULL DEFAULT 0 CHECK (is_web IN (0, 1)),
    -- probed: a probe's answer named it; table: only the usual service of the port number; none: not identified
    ident       TEXT    NOT NULL CHECK (ident IN ('probed', 'table', 'none')),
    state       TEXT    NOT NULL CHECK (state IN ('open', 'closed')),
    first_seen  TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen   TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_run_id TEXT    NOT NULL CHECK (length(last_run_id) BETWEEN 1 AND 96), -- the run that last saw it; runs are pruned, so no key
    UNIQUE (target_id, ip, port, proto),
    CHECK (first_seen <= last_seen)
);

CREATE INDEX exp_service_state_idx ON exp_service (target_id, state);

CREATE TABLE exp_issue (
    id             TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    target_id      TEXT    NOT NULL REFERENCES exp_target (id) ON DELETE CASCADE,
    service_id     TEXT    REFERENCES exp_service (id) ON DELETE SET NULL,
    -- surface | nuclei | zap | openvas | match (exposure.IssueEngine)
    engine         TEXT    NOT NULL CHECK (length(engine) BETWEEN 1 AND 40 AND engine NOT GLOB '*[^a-z0-9_]*'),
    key            TEXT    NOT NULL CHECK (length(key) BETWEEN 1 AND 600),
    title          TEXT    NOT NULL CHECK (length(title) BETWEEN 1 AND 300),
    severity       TEXT    NOT NULL CHECK (severity IN ('critical', 'high', 'medium', 'low', 'info')),
    cves           TEXT    NOT NULL DEFAULT '[]' CHECK (json_valid(cves) AND json_type(cves) = 'array'),
    -- {description, solution, evidence}: for display only
    detail         TEXT    NOT NULL DEFAULT '{}' CHECK (json_valid(detail) AND json_type(detail) = 'object'),
    state          TEXT    NOT NULL CHECK (state IN ('open', 'gone', 'handled')),
    -- patched | mitigated | accepted | not_relevant | false_positive (the findings vocabulary)
    resolution     TEXT    CHECK (resolution IS NULL OR (length(resolution) BETWEEN 1 AND 40 AND resolution NOT GLOB '*[^a-z0-9_]*')),
    resolved_by    TEXT    CHECK (resolved_by IS NULL OR length(resolved_by) BETWEEN 1 AND 320),
    resolved_at    TEXT    CHECK (resolved_at IS NULL OR resolved_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    note           TEXT    CHECK (note IS NULL OR length(note) BETWEEN 1 AND 500),
    accepted_until TEXT    CHECK (accepted_until IS NULL OR accepted_until GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    first_seen     TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_seen      TEXT    NOT NULL CHECK (last_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_run_id    TEXT    NOT NULL CHECK (length(last_run_id) BETWEEN 1 AND 96),
    CHECK ((state = 'handled') = (resolution IS NOT NULL)),
    CHECK ((resolution IS NULL) = (resolved_by IS NULL) AND (resolution IS NULL) = (resolved_at IS NULL)),
    CHECK (accepted_until IS NULL OR resolution = 'accepted'),
    CHECK (first_seen <= last_seen)
);

CREATE UNIQUE INDEX exp_issue_key ON exp_issue (target_id, engine, key, ifnull(service_id, ''));

CREATE INDEX exp_issue_state_idx ON exp_issue (target_id, state);

CREATE INDEX exp_issue_service_idx ON exp_issue (service_id);

CREATE TABLE exp_scan (
    run_id    TEXT NOT NULL PRIMARY KEY REFERENCES core_run (id) ON DELETE CASCADE,
    target_id TEXT NOT NULL REFERENCES exp_target (id) ON DELETE CASCADE,
    mode      TEXT NOT NULL CHECK (mode IN ('surface', 'deep')),
    summary   TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(summary) AND json_type(summary) = 'object')
) WITHOUT ROWID;

CREATE INDEX exp_scan_target_idx ON exp_scan (target_id);

CREATE TABLE exp_attempt (
    id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    ts TEXT    NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE exp_setting (
    id               INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    last_run_at      TEXT CHECK (last_run_at IS NULL OR last_run_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_run_ok      INTEGER CHECK (last_run_ok IS NULL OR last_run_ok IN (0, 1)),
    last_run_message TEXT CHECK (last_run_message IS NULL OR length(last_run_message) <= 1000),
    last_deep_at     TEXT CHECK (last_deep_at IS NULL OR last_deep_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_full_ok_at  TEXT CHECK (last_full_ok_at IS NULL OR last_full_ok_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), greenbone INTEGER NOT NULL DEFAULT 0 CHECK (greenbone IN (0, 1)), greenbone_by TEXT, greenbone_at TEXT, greenbone_sync_at TEXT, greenbone_sync_ok INTEGER CHECK (greenbone_sync_ok IN (0, 1)), greenbone_sync_note TEXT,
    CHECK ((last_run_at IS NULL) = (last_run_ok IS NULL) AND (last_run_at IS NULL) = (last_run_message IS NULL))
);

CREATE TABLE exp_ignored (
    value      TEXT NOT NULL PRIMARY KEY CHECK (length(value) BETWEEN 7 AND 15 AND value GLOB '[0-9]*.[0-9]*.[0-9]*.[0-9]*' AND value NOT GLOB '*[^0-9.]*'),
    ignored_by TEXT NOT NULL CHECK (length(ignored_by) BETWEEN 1 AND 320),
    ignored_at TEXT NOT NULL CHECK (ignored_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE exp_outside (
    target_id  TEXT NOT NULL PRIMARY KEY REFERENCES exp_target (id) ON DELETE CASCADE,
    ip         TEXT NOT NULL CHECK (length(ip) BETWEEN 7 AND 15 AND ip NOT GLOB '*[^0-9.]*'),
    checked_at TEXT NOT NULL CHECK (checked_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    checked_by TEXT NOT NULL CHECK (length(checked_by) BETWEEN 1 AND 320),
    found      INTEGER NOT NULL CHECK (found IN (0, 1)),
    answer     TEXT NOT NULL CHECK (json_valid(answer) AND json_type(answer) = 'object')
);

CREATE INDEX exp_attempt_ts_idx ON exp_attempt (ts);

-- module scan

CREATE TABLE scan_setting (
    id                   INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    stop_on_unresponsive INTEGER NOT NULL DEFAULT 1 CHECK (stop_on_unresponsive IN (0, 1)),
    unresponsive_after   INTEGER NOT NULL DEFAULT 3 CHECK (unresponsive_after BETWEEN 2 AND 20),
    auto_rescan          INTEGER NOT NULL DEFAULT 1 CHECK (auto_rescan IN (0, 1)),
    updated_at           TEXT CHECK (updated_at IS NULL OR updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by           TEXT CHECK (updated_by IS NULL OR length(updated_by) BETWEEN 1 AND 320),
    kev_read_at TEXT CHECK (kev_read_at IS NULL OR kev_read_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), kev_read_cve TEXT NOT NULL DEFAULT '' CHECK (length(kev_read_cve) <= 64));

CREATE TABLE "scan_event" (
    id          TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ts          TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    cve         TEXT NOT NULL UNIQUE CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9]*' AND length(cve) <= 20),
    product     TEXT NOT NULL CHECK (length(product) <= 300),
    devices     TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(devices) AND json_type(devices) = 'array'),
    latency_min REAL CHECK (latency_min IS NULL OR latency_min >= 0),
    run_id      TEXT,
    result      TEXT CHECK (result IS NULL OR result IN ('matched', 'clear', 'skipped_off', 'no_match', 'pick_only', 'stopped', 'expired_no_template', 'expired_scanner', 'expired_zone'))
);

CREATE TABLE "scan_probe" (
    id       TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ts       TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    -- NULL for the probes of an external-surface scan, and once the run is deleted
    run_id   TEXT REFERENCES core_run (id) ON DELETE SET NULL,
    ip       TEXT NOT NULL CHECK (length(ip) BETWEEN 1 AND 253),
    label    TEXT NOT NULL CHECK (length(label) BETWEEN 1 AND 300),
    template TEXT NOT NULL CHECK (length(template) BETWEEN 1 AND 300),
    request  TEXT NOT NULL CHECK (length(request) BETWEEN 1 AND 300),
    -- NULL while the request is on its way
    result   TEXT CHECK (result IS NULL OR result IN ('matched', 'not_matched', 'no_response', 'banner', 'stopped', 'not_run', 'refused'))
);

CREATE INDEX scan_event_ts ON scan_event (ts);

CREATE INDEX scan_probe_ts ON scan_probe (ts);

CREATE INDEX scan_probe_open ON scan_probe (run_id) WHERE result IS NULL;

-- module logs

CREATE TABLE logs_sources (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 64),
    kind       TEXT NOT NULL CHECK (length(kind) BETWEEN 1 AND 32),
    name       TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 64),
    sender_ip  TEXT NOT NULL CHECK (length(sender_ip) BETWEEN 7 AND 15),
    proto      TEXT NOT NULL CHECK (proto IN ('udp', 'tcp', 'tls')),
    port       INTEGER NOT NULL CHECK (port BETWEEN 1 AND 65535),
    created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
, signatures_since TEXT CHECK (signatures_since IS NULL OR signatures_since GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), client_cert_sha256 TEXT NOT NULL DEFAULT '' CHECK (client_cert_sha256 = '' OR (length(client_cert_sha256) = 64 AND client_cert_sha256 NOT GLOB '*[^0-9a-f]*'))) WITHOUT ROWID;

CREATE TABLE logs_retention (
    id   INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    days INTEGER NOT NULL CHECK (days IN (7, 30, 90, 180))
);

CREATE TABLE logs_siem (
    id           INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    enabled      INTEGER NOT NULL CHECK (enabled IN (0, 1)),
    format       TEXT    NOT NULL CHECK (format IN ('syslog', 'cef', 'json')),
    host         TEXT    NOT NULL CHECK (length(host) <= 253),
    port         INTEGER NOT NULL CHECK (port BETWEEN 1 AND 65535),
    proto        TEXT    NOT NULL CHECK (proto IN ('udp', 'tcp', 'tls')),
    url          TEXT    NOT NULL CHECK (length(url) <= 2048),
    secret_id    TEXT    REFERENCES core_secret (id),
    secret_last4 TEXT    CHECK (secret_last4 IS NULL OR length(secret_last4) = 4),
    events       TEXT    NOT NULL CHECK (json_valid(events)),
    last_test    TEXT    CHECK (last_test IS NULL OR json_valid(last_test))
);

CREATE UNIQUE INDEX logs_sources_sender_uq ON logs_sources (sender_ip);

-- module ids

CREATE TABLE ids_alert (
    id           TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 64),
    source       TEXT    NOT NULL CHECK (length(source) BETWEEN 1 AND 40 AND source NOT GLOB '*[^a-z0-9_]*'),
    sid          INTEGER CHECK (sid IS NULL OR sid >= 0),
    signature    TEXT    NOT NULL CHECK (length(signature) BETWEEN 1 AND 300),
    category     TEXT    NOT NULL DEFAULT '' CHECK (length(category) <= 120),
    priority     INTEGER NOT NULL CHECK (priority BETWEEN 1 AND 4),
    src_ip       TEXT    NOT NULL CHECK (length(src_ip) BETWEEN 2 AND 45),
    dst_ip       TEXT    NOT NULL CHECK (length(dst_ip) BETWEEN 2 AND 45),
    dst_port     INTEGER CHECK (dst_port IS NULL OR dst_port BETWEEN 0 AND 65535),
    proto        TEXT    NOT NULL DEFAULT '' CHECK (length(proto) <= 16),
    src_asset_id TEXT    REFERENCES inv_asset (id) ON DELETE SET NULL,
    dst_asset_id TEXT    REFERENCES inv_asset (id) ON DELETE SET NULL,
    first_ts     TEXT    NOT NULL CHECK (first_ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_ts      TEXT    NOT NULL CHECK (last_ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    count        INTEGER NOT NULL CHECK (count >= 1),
    dedupe_key   TEXT    NOT NULL UNIQUE CHECK (length(dedupe_key) = 64),
    CHECK (last_ts >= first_ts)
) STRICT;

CREATE INDEX ids_alert_last_ix ON ids_alert (last_ts);

CREATE INDEX ids_alert_src_asset_ix ON ids_alert (src_asset_id) WHERE src_asset_id IS NOT NULL;

CREATE INDEX ids_alert_dst_asset_ix ON ids_alert (dst_asset_id) WHERE dst_asset_id IS NOT NULL;

CREATE TABLE ids_alert_cve (
    alert_id TEXT NOT NULL REFERENCES ids_alert (id) ON DELETE CASCADE,
    cve      TEXT NOT NULL CHECK (cve GLOB 'CVE-[0-9][0-9][0-9][0-9]-[0-9][0-9][0-9][0-9]*' AND length(cve) <= 20),
    PRIMARY KEY (alert_id, cve)
) STRICT, WITHOUT ROWID;

CREATE INDEX ids_alert_cve_cve_ix ON ids_alert_cve (cve);

-- module ai

CREATE TABLE ai_profile (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name       TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 160),
    name_key   TEXT    NOT NULL UNIQUE CHECK (length(name_key) BETWEEN 1 AND 320),  -- lower-case name: unique in every letter case
    kind       TEXT    NOT NULL CHECK (kind IN ('anthropic', 'openai', 'gemini', 'openai-compatible', 'custom')),
    api_style  TEXT    NOT NULL CHECK (api_style IN ('openai', 'anthropic', 'gemini')),
    base_url   TEXT    NOT NULL CHECK (length(base_url) BETWEEN 1 AND 500),
    model      TEXT    NOT NULL CHECK (length(model) BETWEEN 1 AND 80),
    secret_id  TEXT    REFERENCES core_secret (id),
    key_last4  TEXT    CHECK (key_last4 IS NULL OR length(key_last4) = 4),
    location   TEXT    NOT NULL CHECK (location IN ('internal', 'cloud')),
    created_at TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'), monthly_budget INTEGER NOT NULL DEFAULT 6000000 CHECK (monthly_budget BETWEEN 1000 AND 150000000),
    -- a cloud profile always has a key; an internal one may have none (INV-1)
    CHECK (location = 'internal' OR secret_id IS NOT NULL),
    CHECK ((secret_id IS NULL) = (key_last4 IS NULL))
);

CREATE TABLE ai_assignment (
    job                 TEXT NOT NULL PRIMARY KEY CHECK (job IN ('explain-finding', 'mitigation-config', 'cve-news', 'log-digest', 'log-investigate', 'ask-my-data', 'weekly-report', 'pdpl-assessment', 'translate-advisory', 'response-plan')),
    primary_profile_id  TEXT REFERENCES ai_profile (id) ON DELETE SET NULL,
    fallback_profile_id TEXT REFERENCES ai_profile (id) ON DELETE SET NULL,
    CHECK (fallback_profile_id IS NULL OR primary_profile_id IS NOT NULL),
    CHECK (fallback_profile_id IS NULL OR fallback_profile_id <> primary_profile_id)
);

CREATE TABLE ai_setting (
    key        TEXT NOT NULL PRIMARY KEY CHECK (length(key) BETWEEN 1 AND 40),
    value      TEXT NOT NULL CHECK (json_valid(value)),
    updated_at TEXT NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_by TEXT NOT NULL CHECK (length(updated_by) > 0)
);

CREATE TABLE ai_activity (
    seq         INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    id          TEXT    NOT NULL UNIQUE CHECK (length(id) BETWEEN 1 AND 96),
    ts          TEXT    NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    job         TEXT    NOT NULL CHECK (length(job) BETWEEN 1 AND 64),
    profile     TEXT    NOT NULL CHECK (length(profile) <= 160),
    profile_id  TEXT    CHECK (profile_id IS NULL OR length(profile_id) <= 96),  -- not part of the hash: it only tells the meter whose tokens these are, whatever the profile is called later
    model       TEXT    NOT NULL CHECK (length(model) <= 80),
    trigger     TEXT    NOT NULL CHECK (length(trigger) BETWEEN 1 AND 340),
    hooks       TEXT    NOT NULL CHECK (json_valid(hooks)),
    tools       TEXT    NOT NULL CHECK (json_valid(tools)),
    input_hash  TEXT    NOT NULL CHECK (length(input_hash) = 64),
    output_hash TEXT    NOT NULL CHECK (length(output_hash) = 64),
    summary     TEXT    NOT NULL CHECK (length(summary) <= 600),
    tokens_in   INTEGER NOT NULL CHECK (tokens_in >= 0),
    tokens_out  INTEGER NOT NULL CHECK (tokens_out >= 0),
    result      TEXT    NOT NULL CHECK (result IN ('ok', 'blocked_by_hook', 'fallback_used', 'error')),
    links       TEXT    CHECK (links IS NULL OR json_valid(links)),
    prev_hash   TEXT    NOT NULL CHECK (length(prev_hash) = 64),
    hash        TEXT    NOT NULL CHECK (length(hash) = 64)
, outcome TEXT CHECK (outcome IS NULL OR outcome IN ('capped', 'not_sent')), stop TEXT CHECK (stop IS NULL OR stop IN ('end', 'max_tokens', 'tool_use', 'other')), retried INTEGER NOT NULL DEFAULT 0 CHECK (retried IN (0, 1)));

CREATE TABLE ai_result (
    id          TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    kind        TEXT    NOT NULL CHECK (kind IN ('explain', 'news', 'ask', 'log_digest', 'weekly_summary', 'pdpl_summary')),
    key         TEXT    NOT NULL CHECK (length(key) BETWEEN 1 AND 600),
    inputs_hash TEXT    NOT NULL CHECK (length(inputs_hash) = 64),
    payload     TEXT    NOT NULL CHECK (json_valid(payload)),
    model       TEXT    NOT NULL CHECK (length(model) <= 80),
    profile     TEXT    NOT NULL CHECK (length(profile) <= 160),
    tokens_in   INTEGER NOT NULL CHECK (tokens_in >= 0),
    tokens_out  INTEGER NOT NULL CHECK (tokens_out >= 0),
    asked_by    TEXT    CHECK (asked_by IS NULL OR length(asked_by) <= 320),
    activity_id TEXT,   -- soft reference to ai_activity.id
    created_at  TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE ai_downgrade (
    id        TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ts        TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    from_tier TEXT NOT NULL CHECK (from_tier IN ('min', 'med', 'max')),
    to_tier   TEXT NOT NULL CHECK (to_tier IN ('min', 'med', 'max')),
    reason    TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 300)
);

CREATE TABLE ai_rule (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    text       TEXT    NOT NULL CHECK (length(text) BETWEEN 3 AND 300),
    jobs       TEXT    NOT NULL CHECK (json_valid(jobs) AND json_type(jobs) = 'array'),
    enabled    INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    created_at TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE ai_hook (
    id         TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name       TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 40),
    name_key   TEXT    NOT NULL UNIQUE CHECK (length(name_key) BETWEEN 1 AND 80),  -- lower-case name: unique in every letter case
    "when"     TEXT    NOT NULL CHECK ("when" IN ('before_ai', 'after_ai', 'before_tool')),
    match_type TEXT    NOT NULL CHECK (match_type IN ('keywords', 'regex')),
    pattern    TEXT    NOT NULL CHECK (length(pattern) BETWEEN 1 AND 200),
    action     TEXT    NOT NULL CHECK (action IN ('block', 'mask', 'approve')),
    message    TEXT    NOT NULL CHECK (length(message) BETWEEN 3 AND 200),
    enabled    INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    created_at TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    updated_at TEXT    NOT NULL CHECK (updated_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE ai_hook_state (
    builtin_id TEXT    NOT NULL PRIMARY KEY CHECK (builtin_id IN ('block-pii', 'security-only', 'write-approval')),
    enabled    INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
    CHECK (builtin_id <> 'write-approval' OR enabled = 1)
);

CREATE TABLE ai_memory (
    id           TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    text         TEXT    NOT NULL CHECK (length(text) BETWEEN 3 AND 300),
    source       TEXT    NOT NULL CHECK (source IN ('ai', 'user')),
    created_at   TEXT    NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_used_at TEXT    CHECK (last_used_at IS NULL OR last_used_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    enabled      INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1))
);

CREATE TABLE ai_memory_suggestion (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    text       TEXT NOT NULL CHECK (length(text) BETWEEN 3 AND 300),
    created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    evidence   TEXT NOT NULL CHECK (length(evidence) BETWEEN 1 AND 200)
);

CREATE TABLE ai_memory_rejected (
    digest      TEXT NOT NULL PRIMARY KEY CHECK (length(digest) = 64),
    rejected_at TEXT NOT NULL CHECK (rejected_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

CREATE TABLE ai_skill_state (
    id      TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 40),
    enabled INTEGER NOT NULL CHECK (enabled IN (0, 1))
);

CREATE TABLE ai_knowledge_doc (
    id          TEXT    NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name        TEXT    NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    size        INTEGER NOT NULL CHECK (size BETWEEN 1 AND 10485760),
    status      TEXT    NOT NULL CHECK (status IN ('uploading', 'indexing', 'ready')),
    chunks      INTEGER CHECK (chunks IS NULL OR chunks >= 0),
    jobs        TEXT    NOT NULL CHECK (json_valid(jobs) AND json_type(jobs) = 'array'),
    uploaded_at TEXT    NOT NULL CHECK (uploaded_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    CHECK ((status = 'ready') = (chunks IS NOT NULL))
);

CREATE TABLE ai_knowledge_chunk (
    id     INTEGER NOT NULL PRIMARY KEY,
    doc_id TEXT    NOT NULL REFERENCES ai_knowledge_doc (id) ON DELETE CASCADE,
    seq    INTEGER NOT NULL CHECK (seq >= 1),
    text   TEXT    NOT NULL CHECK (length(text) BETWEEN 1 AND 4000),
    UNIQUE (doc_id, seq)
);

CREATE VIRTUAL TABLE ai_knowledge_chunk_fts USING fts5 (text, content = 'ai_knowledge_chunk', content_rowid = 'id', tokenize = 'unicode61 remove_diacritics 2');

CREATE TABLE ai_read (
    id              TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ts              TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    connection_id   TEXT NOT NULL CHECK (length(connection_id) BETWEEN 1 AND 96),
    connection_name TEXT NOT NULL CHECK (length(connection_name) <= 60),
    tool            TEXT NOT NULL CHECK (length(tool) BETWEEN 1 AND 60),
    job             TEXT NOT NULL CHECK (length(job) BETWEEN 1 AND 32)
);

CREATE INDEX ai_activity_ts ON ai_activity (ts);

CREATE INDEX ai_result_lookup ON ai_result (kind, key, created_at DESC);

CREATE UNIQUE INDEX ai_result_once ON ai_result (kind, key, inputs_hash) WHERE kind IN ('explain', 'news', 'log_digest');

CREATE INDEX ai_downgrade_ts ON ai_downgrade (ts);

CREATE INDEX ai_read_ts ON ai_read (ts);

CREATE TRIGGER ai_activity_no_update BEFORE UPDATE ON ai_activity
BEGIN
    SELECT RAISE(ABORT, 'ai_activity is append-only');
END;

CREATE TRIGGER ai_activity_no_replace BEFORE INSERT ON ai_activity
WHEN EXISTS (SELECT 1 FROM ai_activity WHERE id = NEW.id OR seq = NEW.seq)
BEGIN
    SELECT RAISE(ABORT, 'ai_activity is append-only');
END;

CREATE TRIGGER ai_rule_max BEFORE INSERT ON ai_rule
WHEN (SELECT COUNT(*) FROM ai_rule) >= 30
BEGIN
    SELECT RAISE(ABORT, 'ai_rule: at most 30 rules');
END;

CREATE TRIGGER ai_hook_max BEFORE INSERT ON ai_hook
WHEN (SELECT COUNT(*) FROM ai_hook) >= 30
BEGIN
    SELECT RAISE(ABORT, 'ai_hook: at most 30 custom hooks');
END;

CREATE TRIGGER ai_memory_max BEFORE INSERT ON ai_memory
WHEN (SELECT COUNT(*) FROM ai_memory) >= 100
BEGIN
    SELECT RAISE(ABORT, 'ai_memory: at most 100 memories');
END;

CREATE TRIGGER ai_memory_suggestion_max BEFORE INSERT ON ai_memory_suggestion
WHEN (SELECT COUNT(*) FROM ai_memory_suggestion) >= 50
BEGIN
    SELECT RAISE(ABORT, 'ai_memory_suggestion: at most 50 waiting suggestions');
END;

CREATE TRIGGER ai_knowledge_doc_max BEFORE INSERT ON ai_knowledge_doc
WHEN (SELECT COUNT(*) FROM ai_knowledge_doc) >= 50
BEGIN
    SELECT RAISE(ABORT, 'ai_knowledge_doc: at most 50 documents');
END;

CREATE TRIGGER ai_knowledge_chunk_ai AFTER INSERT ON ai_knowledge_chunk
BEGIN
    INSERT INTO ai_knowledge_chunk_fts (rowid, text) VALUES (new.id, new.text);
END;

CREATE TRIGGER ai_knowledge_chunk_ad AFTER DELETE ON ai_knowledge_chunk
BEGIN
    INSERT INTO ai_knowledge_chunk_fts (ai_knowledge_chunk_fts, rowid, text) VALUES ('delete', old.id, old.text);
END;

-- module reports

CREATE TABLE rep_schedule (
    id           INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    enabled      INTEGER NOT NULL CHECK (enabled IN (0, 1)),
    zone         TEXT NOT NULL CHECK (length(zone) BETWEEN 1 AND 64), -- the box time zone the slots were computed in
    day          INTEGER NOT NULL CHECK (day BETWEEN 1 AND 7),
    hour         INTEGER NOT NULL CHECK (hour BETWEEN 0 AND 23),
    recipients   TEXT NOT NULL CHECK (json_valid(recipients) AND json_type(recipients) = 'array' AND json_array_length(recipients) <= 20),
    armed_at     TEXT NOT NULL,
    last_slot_at TEXT
);

CREATE TABLE rep_history (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    ts         TEXT NOT NULL,
    trigger    TEXT NOT NULL CHECK (trigger IN ('manual', 'scheduled')),
    recipients TEXT NOT NULL CHECK (json_valid(recipients) AND json_type(recipients) = 'array'),
    status     TEXT NOT NULL CHECK (status IN ('sent', 'failed')),
    error      TEXT CHECK (error IS NULL OR length(error) <= 500),
    report     TEXT NOT NULL CHECK (json_valid(report) AND json_type(report) = 'object')
);

CREATE TABLE rep_weekly_ai (
    id      INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    summary TEXT NOT NULL CHECK (json_valid(summary) AND json_type(summary) = 'object')
);

CREATE TABLE rep_pdpl (
    id     INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    org    TEXT CHECK (org IS NULL OR (json_valid(org) AND json_type(org) = 'object')),
    report TEXT CHECK (report IS NULL OR (json_valid(report) AND json_type(report) = 'object'))
);

CREATE INDEX rep_history_ts ON rep_history (ts DESC);

-- module mcp-server

CREATE TABLE mcp_tokens (
    id         TEXT NOT NULL PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 96),
    name       TEXT NOT NULL CHECK (length(name) BETWEEN 1 AND 256),
    -- a JSON array of 1 to 3 distinct scopes out of assets, findings, feeds (checked by the service)
    scopes     TEXT NOT NULL CHECK (json_valid(scopes) AND json_type(scopes) = 'array' AND json_array_length(scopes) BETWEEN 1 AND 3),
    token_hash TEXT NOT NULL UNIQUE CHECK (length(token_hash) = 64),
    last4      TEXT NOT NULL CHECK (length(last4) = 4),
    created_at TEXT NOT NULL CHECK (created_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    last_used  TEXT CHECK (last_used IS NULL OR last_used GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
);

-- ======== logs.db ========

-- schema epoch (core/store)

CREATE TABLE core_schema_epoch (
    id    INTEGER NOT NULL PRIMARY KEY CHECK (id = 1),
    epoch INTEGER NOT NULL CHECK (epoch >= 1),
    rev   TEXT    NOT NULL CHECK (length(rev) = 64)
);

-- module logs

CREATE TABLE logs_events (
    id        INTEGER PRIMARY KEY AUTOINCREMENT, -- never reused: the API id le-N names one line for ever
    ts        TEXT NOT NULL CHECK (ts GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    source_id TEXT NOT NULL CHECK (length(source_id) BETWEEN 1 AND 64),
    line      TEXT NOT NULL CHECK (length(line) <= 8192)
);

CREATE TABLE logs_source_buckets (
    source_id TEXT    NOT NULL,
    bucket    INTEGER NOT NULL, -- unix seconds / 300
    lines     INTEGER NOT NULL CHECK (lines >= 0),
    PRIMARY KEY (source_id, bucket)
) WITHOUT ROWID;

CREATE TABLE logs_source_seen (
    source_id     TEXT NOT NULL PRIMARY KEY,
    last_received TEXT NOT NULL CHECK (last_received GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z')
) WITHOUT ROWID;

CREATE TABLE logs_volume (
    id         INTEGER PRIMARY KEY CHECK (id = 1),
    line_bytes INTEGER NOT NULL CHECK (line_bytes >= 0)
);

CREATE TABLE logs_signature_daily (
    day        TEXT    NOT NULL CHECK (day GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'),
    source_id  TEXT    NOT NULL CHECK (length(source_id) BETWEEN 1 AND 64),
    signature  TEXT    NOT NULL CHECK (length(signature) BETWEEN 1 AND 256),
    dest       TEXT    NOT NULL CHECK (length(dest) <= 64),
    count      INTEGER NOT NULL CHECK (count > 0),
    first_seen TEXT    NOT NULL CHECK (first_seen GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    sample     TEXT    NOT NULL CHECK (length(sample) <= 512),
    mined      INTEGER NOT NULL CHECK (mined IN (0, 1)),
    PRIMARY KEY (day, source_id, signature)
) WITHOUT ROWID;

CREATE TABLE logs_signature_buckets (
    source_id TEXT    NOT NULL CHECK (length(source_id) BETWEEN 1 AND 64),
    bucket    INTEGER NOT NULL, -- unix seconds / 300
    sig_hash  INTEGER NOT NULL,
    count     INTEGER NOT NULL CHECK (count > 0),
    mined     INTEGER NOT NULL CHECK (mined IN (0, 1)),
    PRIMARY KEY (bucket, source_id, sig_hash)
) WITHOUT ROWID;

CREATE TABLE logs_anomaly_sent (
    source_id TEXT NOT NULL CHECK (length(source_id) BETWEEN 1 AND 64),
    kind      TEXT NOT NULL CHECK (kind IN ('new', 'spike', 'summary', 'covered')),
    signature TEXT NOT NULL CHECK (length(signature) BETWEEN 1 AND 256),
    ref       TEXT NOT NULL,
    target    TEXT NOT NULL,
    bounded   INTEGER NOT NULL CHECK (bounded IN (0, 1)), -- the room of the hour that the event used: bounded signatures have their own
    sent_at   TEXT NOT NULL CHECK (sent_at GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9]Z'),
    PRIMARY KEY (source_id, kind, signature, ref)
) WITHOUT ROWID;

CREATE TABLE logs_signature_addrs (
    source_id TEXT    NOT NULL CHECK (length(source_id) BETWEEN 1 AND 64),
    bucket    INTEGER NOT NULL, -- unix seconds / 300
    sig_hash  INTEGER NOT NULL,
    addr      BLOB    NOT NULL CHECK (length(addr) IN (4, 16)), -- the 4 or 16 bytes of the address (an IPv4-mapped one is stored as IPv4)
    count     INTEGER NOT NULL CHECK (count > 0),
    PRIMARY KEY (bucket, source_id, sig_hash, addr)
) WITHOUT ROWID;

CREATE TABLE logs_ioc_hits (
    id         TEXT    PRIMARY KEY CHECK (length(id) BETWEEN 1 AND 64),
    ts         TEXT    NOT NULL,
    src_ip     TEXT    NOT NULL CHECK (length(src_ip) BETWEEN 7 AND 15),
    dest       TEXT    NOT NULL CHECK (length(dest) BETWEEN 1 AND 253),
    dest_kind  TEXT    NOT NULL CHECK (dest_kind IN ('ip', 'domain')),
    seen_via   TEXT    NOT NULL CHECK (length(seen_via) BETWEEN 1 AND 128),
    feeds      TEXT    NOT NULL CHECK (json_valid(feeds)),
    confidence REAL    NOT NULL CHECK (confidence BETWEEN 0 AND 1),
    source_id  TEXT    NOT NULL CHECK (length(source_id) BETWEEN 1 AND 64)
, blocked INTEGER NOT NULL DEFAULT 0, listed_as TEXT NOT NULL DEFAULT '');

CREATE INDEX logs_events_ts ON logs_events (ts);

CREATE INDEX logs_events_source_ts ON logs_events (source_id, ts);

CREATE INDEX logs_signature_daily_source ON logs_signature_daily (source_id, signature, day);

CREATE INDEX logs_signature_buckets_source ON logs_signature_buckets (source_id, sig_hash, bucket);

CREATE INDEX logs_signature_addrs_source ON logs_signature_addrs (source_id, sig_hash, bucket);

CREATE INDEX logs_ioc_hits_ts ON logs_ioc_hits (ts);

CREATE INDEX logs_ioc_hits_pair ON logs_ioc_hits (src_ip, dest, ts);

CREATE INDEX logs_ioc_hits_listed ON logs_ioc_hits (src_ip, listed_as, ts);
